    /// Verifies that the Search demo renders every official style and layout with keyboard-reachable results.
    @Test
    void searchPageRendersAllStylesLayoutsAndKeyboardReachableResults() throws InterruptedException {
        AtomicReference<@Nullable Stage> stageReference = new AtomicReference<>();
        AtomicReference<@Nullable M3FXDemoApp> appReference = new AtomicReference<>();
        AtomicReference<@Nullable Scene> sceneReference = new AtomicReference<>();

        FxTestUtils.runOnFxThread(() -> {
            Stage stage = new Stage();
            M3FXDemoApp app = new M3FXDemoApp();
            app.start(stage);
            stage.setWidth(1280.0);
            stage.setHeight(900.0);

            stageReference.set(stage);
            appReference.set(app);
            sceneReference.set(Objects.requireNonNull(app.activeScene(), "scene"));
        });

        try {
            FxTestUtils.assertNoCssWarningsInterruptibly(() -> showPageWhenSidebarSelectionSettled(
                    appReference, sceneReference, "Search", scene -> {
                    }, () -> {
                        Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
                        assertCurrentPageTitle(scene, "Search");

                        Node page = currentDemoPage(scene, "Search");
                        List<M3SearchView> searchViews = visibleNodesOfType(page, M3SearchView.class);
                        assertEquals(4, searchViews.size(), "Search page should show the four style and layout combinations");
                        M3SearchView activeView = Objects.requireNonNull(
                                searchViews.stream()
                                        .filter(view -> view.getViewStyle() == M3SearchViewStyle.CONTAINED
                                                && view.getViewLayout() == M3SearchViewLayout.DOCKED)
                                        .findFirst()
                                        .orElse(null),
                                "contained docked search view"
                        );

                        List<M3SearchBar> searchBars = visibleNodesOfType(page, M3SearchBar.class);
                        assertEquals(6, searchBars.size(),
                                "Search page should expose two standalone bars and four embedded search bars");
                        searchBars.forEach(M3FXDemoVisualMatrixTest::assertSearchBarVisualGeometry);

                        for (M3SearchView searchView : searchViews) {
                            assertSearchViewResultsVisible(searchView, searchView.getResults().size());
                            assertActiveSearchViewDemoGeometry(searchView);
                        }

                        M3ListItem firstResult = assertInstanceOf(M3ListItem.class, activeView.getResults().get(0));
                        searchViewEditor(activeView).requestFocus();
                        searchViewEditor(activeView).fireEvent(new KeyEvent(KeyEvent.KEY_PRESSED, "", "", KeyCode.DOWN, false, false, false, false));
                        scene.getRoot().applyCss();
                        scene.getRoot().layout();

                        @Nullable Node focusOwner = scene.getFocusOwner();
                        assertNotNull(focusOwner, "search result keyboard navigation should produce a focus owner");
                        assertTrue(isNodeOrDescendant(firstResult, focusOwner),
                                () -> "DOWN from the search editor should focus the first result: focusOwner=" + focusOwner);

                        WritableImage image = snapshotNode(activeView);
                        writeVisualSnapshot(image, Path.of(
                                "build",
                                "reports",
                                "m3fx-demo-visual",
                                "search-active-view.png"
                        ));
                        assertSnapshotHasVisibleContent(image, "Search active view");
                    }));
        } finally {
            FxTestUtils.runOnFxThread(() -> {
                Stage stage = stageReference.get();
                if (stage != null) {
                    stage.close();
                }
            });
        }
    }

    /// Verifies that the Cards demo renders variant, media, action, and disabled states.
    @Test
    void cardsPageRendersVariantsMediaActionsAndStates() throws InterruptedException {
        AtomicReference<@Nullable Stage> stageReference = new AtomicReference<>();
        AtomicReference<@Nullable M3FXDemoApp> appReference = new AtomicReference<>();
        AtomicReference<@Nullable Scene> sceneReference = new AtomicReference<>();

        FxTestUtils.runOnFxThread(() -> {
            Stage stage = new Stage();
            M3FXDemoApp app = new M3FXDemoApp();
            app.start(stage);
            stage.setWidth(1280.0);
            stage.setHeight(900.0);

            stageReference.set(stage);
            appReference.set(app);
            sceneReference.set(Objects.requireNonNull(app.activeScene(), "scene"));
        });

        try {
            FxTestUtils.assertNoCssWarningsInterruptibly(() -> showPageWhenSidebarSelectionSettled(
                    appReference, sceneReference, "Cards", scene -> {
                    }, () -> {
                        Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
                        Node page = currentDemoPage(scene, "Cards");
                        assertCurrentPageTitle(scene, "Cards");

                        List<M3Card> cards = visibleNodesOfType(page, M3Card.class);
                        assertEquals(9, cards.size(), "Cards page should render variant, passive, and state examples");
                        assertEquals(3, cards.stream().filter(card -> card.getVariant() == M3CardVariant.FILLED).count());
                        assertEquals(3, cards.stream().filter(card -> card.getVariant() == M3CardVariant.OUTLINED).count());
                        assertEquals(3, cards.stream().filter(card -> card.getVariant() == M3CardVariant.ELEVATED).count());
                        assertEquals(6, cards.stream().filter(card -> card.getOnAction() != null).count(),
                                "demo cards should distinguish direct actions from passive containers");
                        assertEquals(3, cards.stream().filter(card -> card.getOnAction() == null).count(),
                                "media cards with nested actions should keep their surfaces passive");
                        assertEquals(1, cards.stream().filter(M3Card::isDragged).count(),
                                "Cards page should include one dragged state");
                        assertEquals(1, cards.stream().filter(Node::isDisabled).count(),
                                "Cards page should include one disabled card state");

                        assertEquals(3, visibleNodesWithStyle(page, "demo-card-media").size(),
                                "Cards page should render three media cards");
                        assertEquals(3, visibleNodesWithStyle(page, "demo-card-actions").size(),
                                "Cards page should render action rows for the media cards");
                        long cardActionButtons = visibleNodesOfType(page, M3Button.class).stream()
                                .filter(button -> nearestAncestorOfType(button, M3Card.class) != null)
                                .count();
                        assertEquals(6, cardActionButtons, "media cards should expose two actions each");

                        for (M3Card card : cards) {
                            assertCardDemoGeometry(card);
                            assertNotNull(firstVisibleStyledDescendant(card, "demo-card-title"),
                                    "each demo card should render a title");
                            assertNotNull(firstVisibleStyledDescendant(card, "demo-card-body"),
                                    "each demo card should render supporting text");
                        }

                        WritableImage image = snapshot(scene);
                        writeVisualSnapshot(image, Path.of(
                                "build",
                                "reports",
                                "m3fx-demo-visual",
                                "cards-rich-states.png"
                        ));
                        assertSnapshotHasVisibleContent(image, "Cards rich states");

                        ScrollPane pageScrollPane = demoPageScrollPane(scene);
                        pageScrollPane.setVvalue(1.0);
                        scene.getRoot().applyCss();
                        scene.getRoot().layout();
                        Bounds sceneBounds = scene.getRoot().localToScene(scene.getRoot().getLayoutBounds());
                        assertTrue(cards.stream()
                                        .filter(card -> firstVisibleStyledDescendant(card, "demo-card-actions") != null)
                                        .anyMatch(card -> !isOutsideSceneViewport(
                                                card,
                                                card.localToScene(card.getLayoutBounds()),
                                                sceneBounds
                                        )),
                                "Cards page should render media card actions in a captured viewport");
                        assertTrue(cards.stream()
                                        .filter(Node::isDisabled)
                                        .anyMatch(card -> !isOutsideSceneViewport(
                                                card,
                                                card.localToScene(card.getLayoutBounds()),
                                                sceneBounds
                                        )),
                                "Cards page should render the disabled card state in a captured viewport");

                        WritableImage mediaImage = snapshot(scene);
                        writeVisualSnapshot(mediaImage, Path.of(
                                "build",
                                "reports",
                                "m3fx-demo-visual",
                                "cards-media-actions.png"
                        ));
                        assertSnapshotHasVisibleContent(mediaImage, "Cards media and actions");
                    }));
        } finally {
            FxTestUtils.runOnFxThread(() -> {
                Stage stage = stageReference.get();
                if (stage != null) {
                    stage.close();
                }
            });
        }
    }

    /// Verifies that the Carousel demo renders all Material layouts and focal selection.
    @Test
    void carouselPageRendersViewportAndSelection() throws InterruptedException {
        AtomicReference<@Nullable Stage> stageReference = new AtomicReference<>();
        AtomicReference<@Nullable M3FXDemoApp> appReference = new AtomicReference<>();
        AtomicReference<@Nullable Scene> sceneReference = new AtomicReference<>();
        AtomicReference<@Nullable M3Carousel> multiBrowseReference = new AtomicReference<>();
        AtomicReference<@Nullable M3Carousel> uncontainedReference = new AtomicReference<>();

        FxTestUtils.runOnFxThread(() -> {
            Stage stage = new Stage();
            M3FXDemoApp app = new M3FXDemoApp();
            app.start(stage);
            stage.setWidth(1280.0);
            stage.setHeight(900.0);

            stageReference.set(stage);
            appReference.set(app);
            sceneReference.set(Objects.requireNonNull(app.activeScene(), "scene"));
        });

        try {
            showPageWhenSidebarSelectionSettled(appReference, sceneReference, "Carousel", scene -> {
            }, () -> {
                Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
                Parent root = scene.getRoot();
                Node page = currentDemoPage(scene, "Carousel");
                assertCurrentPageTitle(scene, "Carousel");
                assertVisibleText(root, "Multi-browse", "Carousel");
                assertVisibleText(root, "Hero", "Carousel");
                assertVisibleText(root, "Center-aligned hero", "Carousel");
                assertVisibleText(root, "Uncontained", "Carousel");
                assertVisibleText(root, "Uncontained multi-aspect ratio", "Carousel");
                assertVisibleText(root, "Full-screen", "Carousel");
                assertVisibleText(root, "Show all", "Carousel");

                List<M3Carousel> carousels = visibleNodesOfType(page, M3Carousel.class);
                assertEquals(6, carousels.size(),
                        () -> "Carousel page should render six Material layouts, found " + carousels.size());
                for (M3CarouselLayout layout : M3CarouselLayout.values()) {
                    M3Carousel carousel = carouselWithLayout(carousels, layout);
                    assertCarouselDemoGeometry(carousel, layout + " carousel");
                }
                assertCarouselRoleGeometry(
                        carouselWithLayout(carousels, M3CarouselLayout.MULTI_BROWSE),
                        3,
                        true,
                        "multi-browse carousel"
                );
                assertCarouselRoleGeometry(
                        carouselWithLayout(carousels, M3CarouselLayout.HERO),
                        2,
                        true,
                        "hero carousel"
                );
                assertCarouselRoleGeometry(
                        carouselWithLayout(carousels, M3CarouselLayout.CENTER_ALIGNED_HERO),
                        2,
                        true,
                        "center-aligned hero carousel"
                );
                assertCarouselRoleGeometry(
                        carouselWithLayout(carousels, M3CarouselLayout.UNCONTAINED),
                        1,
                        false,
                        "uncontained carousel"
                );
                assertCarouselRoleGeometry(
                        carouselWithLayout(carousels, M3CarouselLayout.UNCONTAINED_MULTI_ASPECT_RATIO),
                        3,
                        false,
                        "multi-aspect-ratio carousel"
                );
                assertCarouselRoleGeometry(
                        carouselWithLayout(carousels, M3CarouselLayout.FULL_SCREEN),
                        1,
                        false,
                        "full-screen carousel"
                );
                M3Carousel fullScreen = carouselWithLayout(carousels, M3CarouselLayout.FULL_SCREEN);
                ScrollPane fullScreenViewport = assertInstanceOf(
                        ScrollPane.class,
                        requireVisibleStyledDescendant(
                                fullScreen,
                                "m3-carousel-viewport",
                                "full-screen carousel viewport"
                        )
                );
                Node fullScreenViewportNode = Objects.requireNonNull(
                        fullScreenViewport.lookup(".viewport"),
                        "full-screen carousel viewport node"
                );
                Node fullScreenTrack = requireVisibleStyledDescendant(
                        fullScreen,
                        "m3-carousel-track",
                        "full-screen carousel track"
                );
                Bounds fullScreenViewportBounds =
                        fullScreenViewportNode.localToScene(fullScreenViewportNode.getLayoutBounds());
                Bounds fullScreenTrackBounds = fullScreenTrack.localToScene(fullScreenTrack.getLayoutBounds());
                assertTrue(
                        fullScreenTrackBounds.getHeight() > fullScreenViewportBounds.getHeight() * 2.0,
                        () -> "full-screen carousel should stack vertical pages: track="
                                + fullScreenTrackBounds + ", viewport=" + fullScreenViewportBounds
                );
                for (Node item : fullScreen.getItems()) {
                    Node mask = carouselItemMask(item, "full-screen carousel");
                    Bounds maskBounds = mask.localToScene(mask.getLayoutBounds());
                    assertEquals(fullScreenViewportBounds.getWidth(), maskBounds.getWidth(), 1.5,
                            "full-screen item width should fill its viewport");
                    assertEquals(fullScreenViewportBounds.getHeight(), maskBounds.getHeight(), 1.5,
                            "full-screen item height should fill its viewport");
                }

                M3Carousel multiBrowse = carouselWithLayout(carousels, M3CarouselLayout.MULTI_BROWSE);
                M3Carousel uncontained = carouselWithLayout(carousels, M3CarouselLayout.UNCONTAINED);
                assertEquals(0, multiBrowse.getSelectedIndex(), "multi-browse carousel selected index");
                assertEquals(0, uncontained.getSelectedIndex(), "uncontained carousel selected index");
                assertEquals(
                        2,
                        carouselWithLayout(carousels, M3CarouselLayout.CENTER_ALIGNED_HERO).getSelectedIndex(),
                        "center-aligned hero selected index"
                );
                assertCarouselTrackFillsViewport(uncontained, "uncontained carousel");
                assertCarouselTrackFillsViewport(
                        carouselWithLayout(carousels, M3CarouselLayout.UNCONTAINED_MULTI_ASPECT_RATIO),
                        "multi-aspect-ratio carousel"
                );

                multiBrowseReference.set(multiBrowse);
                uncontainedReference.set(uncontained);

                WritableImage image = snapshot(scene);
                writeVisualSnapshot(image, Path.of(
                        "build",
                        "reports",
                        "m3fx-demo-visual",
                        "carousel-layouts.png"
                ));
                assertSnapshotHasVisibleContent(image, "Carousel layouts");

                WritableImage fullPageImage = snapshotNode(page);
                writeVisualSnapshot(fullPageImage, Path.of(
                        "build",
                        "reports",
                        "m3fx-demo-visual",
                        "carousel-full-page.png"
                ));
                assertSnapshotHasVisibleContent(fullPageImage, "Carousel full page");
            });

            FxTestUtils.runOnFxThreadWhenStable(() -> {
                @Nullable Scene scene = sceneReference.get();
                @Nullable M3Carousel multiBrowse = multiBrowseReference.get();
                @Nullable M3Carousel uncontained = uncontainedReference.get();
                if (scene == null || multiBrowse == null || uncontained == null) {
                    return false;
                }
                scene.getRoot().applyCss();
                scene.getRoot().layout();
                return multiBrowse.getSelectedIndex() == 1
                        && uncontained.getSelectedIndex() == 0
                        && hasRenderableBounds(multiBrowse)
                        && hasRenderableBounds(uncontained);
            }, SETTLED_STATE_PULSES, () -> {
                Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
                M3Carousel multiBrowse = Objects.requireNonNull(multiBrowseReference.get(), "multi-browse carousel");
                M3MotionSettings.setReducedMotionRequested(multiBrowse, true);
                multiBrowse.setAnimatedScroll(false);
                multiBrowse.selectNext();
                scene.getRoot().applyCss();
                scene.getRoot().layout();
                multiBrowse.scrollSelectedItemIntoView(false);
            }, () -> {
                Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
                M3Carousel multiBrowse = Objects.requireNonNull(multiBrowseReference.get(), "multi-browse carousel");
                M3Carousel uncontained = Objects.requireNonNull(uncontainedReference.get(), "uncontained carousel");
                assertEquals(1, multiBrowse.getSelectedIndex(), "selection should advance to Design review");
                assertEquals(0, uncontained.getSelectedIndex(), "uncontained carousel should remain unchanged");
                assertCarouselDemoGeometry(multiBrowse, "multi-browse carousel after selection");
                assertCarouselDemoGeometry(uncontained, "uncontained carousel after selection");

                WritableImage image = snapshot(scene);
                writeVisualSnapshot(image, Path.of(
                        "build",
                        "reports",
                        "m3fx-demo-visual",
                        "carousel-after-selection.png"
                ));
                assertSnapshotHasVisibleContent(image, "Carousel after selection");
            });
        } finally {
            FxTestUtils.runOnFxThread(() -> {
                @Nullable M3Carousel multiBrowse = multiBrowseReference.get();
                if (multiBrowse != null) {
                    multiBrowse.setAnimatedScroll(true);
                    M3MotionSettings.setReducedMotionRequested(multiBrowse, false);
                }
                Stage stage = stageReference.get();
                if (stage != null) {
                    stage.close();
                }
            });
        }
    }

