    /// Verifies one focused multiline text input content surface and floating label geometry.
    private static void assertFocusedMultilineTextInputSurfaceContract(
            Scene scene,
            M3TextInputLayout layout,
            String description
    ) {
        scrollDemoPageNodeIntoView(scene, layout);
        TextInputControl input = Objects.requireNonNull(layout.getInput(), () -> description + " input");
        input.requestFocus();
        scene.getRoot().applyCss();
        scene.getRoot().layout();
        assertTrue(input.isFocused(), () -> description + " should own focus before capture");
        if (input instanceof M3TextInput textInput
                && textInput.getVariant() == M3TextInputVariant.OUTLINED) {
            javafx.scene.shape.Path outline = assertInstanceOf(
                    javafx.scene.shape.Path.class,
                    layout.lookup("." + "m3-text-input-outline")
            );
            assertTrue(outline.getPseudoClassStates().contains(PseudoClass.getPseudoClass("focused")),
                    () -> description + " outline should expose the focused pseudo-class");
            assertEquals(3.0, outline.getStrokeWidth(), 0.0001,
                    () -> description + " should use the MD3 3dp focused outline");
            M3Theme theme = Objects.requireNonNull(
                    M3ThemeManager.getTheme(scene),
                    () -> description + " theme"
            );
            assertEquals(
                    theme.colorScheme().getColor(org.glavo.monetfx.ColorRole.PRIMARY),
                    outline.getStroke(),
                    () -> description + " should use the MD3 primary focused outline color"
            );
            assertEquals(1.0, outline.getOpacity(), 0.0001,
                    () -> description + " focused outline should be fully opaque");
        }
        WritableImage focusedAreaImage = requireSnapshotWithNodeFullyVisible(scene, layout, description);
        writeVisualSnapshot(focusedAreaImage, Path.of(
                "build",
                "reports",
                "m3fx-demo-visual",
                "text-input-" + snapshotFileName(description) + ".png"
        ));
        assertSnapshotHasVisibleContent(focusedAreaImage, description);
        assertFocusedTextAreaContentBackgroundMatchesContainer(focusedAreaImage, layout, description);
        if (input instanceof M3TextInput textInput && textInput.getVariant() == M3TextInputVariant.OUTLINED) {
            assertOutlinedFloatingLabelGeometry(layout, description);
            assertOutlinedFloatingLabelBackgroundMatchesSurrounding(focusedAreaImage, layout, description);
        }
        assertTextInputFloatingLabelInkAvoidsInputInk(focusedAreaImage, layout, description);
    }

    /// Verifies that mirrored text inputs keep logical slots and text geometry separated.
    private static void assertMirroredTextInputLayoutContracts(Scene scene, List<M3TextInputLayout> layouts) {
        M3TextInputLayout filledLayout = requireTextInputLayout(
                layouts,
                "support@example.com",
                "Filled with text"
        );
        M3TextInputLayout outlinedLayout = requireTextInputLayout(layouts, "M3FX", "Outlined with text");
        M3TextInputLayout passwordLayout = requireTextInputLayout(layouts, "", "Password");
        M3TextInputLayout outlinedAreaLayout = requireTextInputLayout(
                layouts,
                "Material text areas share field colors but keep multi-line height tokens.",
                "Outlined text area"
        );

        assertRightToLeftTextInputLayoutGeometry(filledLayout, "mirrored filled text input");
        assertRightToLeftTextInputLayoutGeometry(outlinedLayout, "mirrored outlined text input");
        assertRightToLeftTextInputLayoutGeometry(passwordLayout, "mirrored password text input");
        assertRightToLeftTextInputLayoutGeometry(outlinedAreaLayout, "mirrored outlined multiline text input");

        scrollAncestorScrollPanesNodeIntoView(outlinedLayout);
        WritableImage mirroredImage = requireSnapshotWithNodeFullyVisible(
                scene,
                outlinedLayout,
                "mirrored outlined text input"
        );
        writeVisualSnapshot(mirroredImage, Path.of(
                "build",
                "reports",
                "m3fx-demo-visual",
                "text-input-mirrored-layout-contracts.png"
        ));
        assertSnapshotHasVisibleContent(mirroredImage, "Mirrored text input layout contracts");
        assertOutlinedFloatingLabelBackgroundMatchesSurrounding(
                mirroredImage,
                outlinedLayout,
                "mirrored outlined text input"
        );
        assertTextInputFloatingLabelInkAvoidsAdornmentSlots(
                mirroredImage,
                outlinedLayout,
                "mirrored outlined text input"
        );
        assertTextInputFloatingLabelInkAvoidsInputInk(
                mirroredImage,
                outlinedLayout,
                "mirrored outlined text input"
        );
        assertSingleLineTextInputsHaveVerticalRoom(scene, "Mirrored Text Fields");

        Node root = scene.getRoot();
        boolean previousReducedMotionRequested = M3MotionSettings.isReducedMotionRequested(root);
        M3MotionSettings.setReducedMotionRequested(root, true);
        try {
            TextInputControl outlinedInput = Objects.requireNonNull(
                    outlinedLayout.getInput(),
                    "mirrored outlined input"
            );
            outlinedInput.requestFocus();
            scene.getRoot().applyCss();
            scene.getRoot().layout();
            WritableImage focusedMirroredImage = requireSnapshotWithNodeFullyVisible(
                    scene,
                    outlinedLayout,
                    "focused mirrored outlined text input"
            );
            writeVisualSnapshot(focusedMirroredImage, Path.of(
                    "build",
                    "reports",
                    "m3fx-demo-visual",
                    "text-input-focused-rtl-outlined-contracts.png"
            ));
            assertSnapshotHasVisibleContent(focusedMirroredImage, "Focused mirrored outlined text input contracts");
            assertOutlinedFloatingLabelBackgroundMatchesSurrounding(
                    focusedMirroredImage,
                    outlinedLayout,
                    "focused mirrored outlined text input"
            );
            assertTextInputFloatingLabelInkAvoidsAdornmentSlots(
                    focusedMirroredImage,
                    outlinedLayout,
                    "focused mirrored outlined text input"
            );
            assertTextInputFloatingLabelInkAvoidsInputInk(
                    focusedMirroredImage,
                    outlinedLayout,
                    "focused mirrored outlined text input"
            );
            Text focusedMirroredText = Objects.requireNonNull(
                    firstVisibleText(outlinedInput),
                    "focused mirrored outlined input text"
            );
            assertSingleLineTextInputHasVerticalRoom(
                    focusedMirroredImage,
                    outlinedLayout,
                    outlinedInput,
                    focusedMirroredText,
                    "Focused mirrored Text Fields"
            );

            TextInputControl passwordInput = Objects.requireNonNull(
                    passwordLayout.getInput(),
                    "mirrored password input"
            );
            passwordInput.requestFocus();
            scene.getRoot().applyCss();
            scene.getRoot().layout();
            WritableImage focusedPasswordImage = requireSnapshotWithNodeFullyVisible(
                    scene,
                    passwordLayout,
                    "focused mirrored password input"
            );
            writeVisualSnapshot(focusedPasswordImage, Path.of(
                    "build",
                    "reports",
                    "m3fx-demo-visual",
                    "text-input-focused-rtl-outlined-action-contracts.png"
            ));
            assertTextInputFocusedVisualState(
                    focusedPasswordImage,
                    passwordLayout,
                    passwordInput,
                    "focused mirrored password input"
            );
            assertSingleLineTextInputsHaveVerticalRoom(scene, "Focused Mirrored Text Fields");
        } finally {
            M3MotionSettings.setReducedMotionRequested(root, previousReducedMotionRequested);
        }
    }

    /// Verifies every focusable text input state exposed by the demo page.
    private static void assertFocusedTextInputStateMatrix(
            Scene scene,
            List<M3TextInputLayout> layouts,
            String modeName
    ) {
        Node root = scene.getRoot();
        boolean previousReducedMotionRequested = M3MotionSettings.isReducedMotionRequested(root);
        M3MotionSettings.setReducedMotionRequested(root, true);
        int focusedLayouts = 0;
        try {
            for (M3TextInputLayout layout : layouts) {
                @Nullable TextInputControl input = layout.getInput();
                if (input == null || input.isDisabled() || !input.isFocusTraversable()) {
                    continue;
                }

                scrollDemoPageNodeIntoView(scene, layout);
                input.requestFocus();
                input.deselect();
                input.positionCaret(input.getLength());
                scene.getRoot().applyCss();
                scene.getRoot().layout();

                String description = modeName + " focused text input `"
                        + layout.getLabelText() + "`";
                assertTrue(input.isFocused(), () -> description + " should accept focus");
                assertTextInputLayoutContainerGeometry(layout, description);
                if (layout.getEffectiveNodeOrientation() == NodeOrientation.RIGHT_TO_LEFT) {
                    assertRightToLeftTextInputLayoutGeometry(layout, description);
                }
                if (layout.getTrailing() != null) {
                    assertTextInputTrailingActionGeometry(layout, description);
                }
                if (firstVisibleStyledDescendant(layout, "m3-text-input-clear-button") != null) {
                    assertTextInputClearButtonGeometry(layout, description);
                }

                WritableImage image = requireSnapshotWithNodeFullyVisible(scene, layout, description);
                assertTextInputFocusedVisualState(image, layout, input, description);
                focusedLayouts++;
            }
        } finally {
            M3MotionSettings.setReducedMotionRequested(root, previousReducedMotionRequested);
        }

        int checkedLayouts = focusedLayouts;
        assertTrue(checkedLayouts >= 8,
                () -> modeName + " should verify the focused text input state matrix, checked="
                        + checkedLayouts + ", totalLayouts=" + layouts.size());
    }

    /// Verifies one focused text input with rendered-pixel assertions.
    private static void assertTextInputFocusedVisualState(
            WritableImage image,
            M3TextInputLayout layout,
            TextInputControl input,
            String description
    ) {
        assertSnapshotHasVisibleContent(image, description);
        if (input instanceof M3TextInput textInput && textInput.getVariant() == M3TextInputVariant.OUTLINED
                && layout.isLabelFloating()) {
            assertOutlinedFloatingLabelGeometry(layout, description);
            assertOutlinedFloatingLabelBackgroundMatchesSurrounding(image, layout, description);
        }

        assertTextInputFloatingLabelInkAvoidsAdornmentSlots(image, layout, description);
        assertTextInputFloatingLabelInkAvoidsInputInk(image, layout, description);

        if (input instanceof M3TextArea) {
            assertFocusedTextAreaContentBackgroundMatchesContainer(image, layout, description);
            return;
        }

        @Nullable Text text = firstVisibleText(input);
        if (text != null && hasRenderableBounds(text) && isSingleLineTextInputWithMeasurableGlyph(input)) {
            assertSingleLineTextInputHasVerticalRoom(image, layout, input, text, description);
        }
    }

