    /// Verifies the sidebar remains scrollable after every collapsible drawer group is expanded.
    @Test
    void sidebarAllExpandedGroupsCanScrollToLastDestination() throws InterruptedException {
        AtomicReference<@Nullable Stage> stageReference = new AtomicReference<>();
        AtomicReference<@Nullable M3FXDemoApp> appReference = new AtomicReference<>();
        AtomicReference<@Nullable Scene> sceneReference = new AtomicReference<>();

        FxTestUtils.runOnFxThread(() -> {
            Stage stage = new Stage();
            M3FXDemoApp app = new M3FXDemoApp();
            app.start(stage);
            stage.setWidth(1280.0);
            stage.setHeight(720.0);

            stageReference.set(stage);
            appReference.set(app);
            sceneReference.set(Objects.requireNonNull(app.activeScene(), "scene"));
        });

        try {
            FxTestUtils.runOnFxThreadWhenStable(
                    () -> {
                        Scene scene = sceneReference.get();
                        if (scene == null) {
                            return false;
                        }
                        scene.getRoot().applyCss();
                        scene.getRoot().layout();

                        List<M3NavigationDrawerGroup> groups = demoSidebarDrawerGroups(scene.getRoot());
                        if (groups.isEmpty() || groups.stream().anyMatch(group -> !group.isExpanded())) {
                            return false;
                        }

                        @Nullable ScrollPane scrollPane = demoSidebarViewport(scene.getRoot());
                        if (scrollPane == null) {
                            return false;
                        }
                        scrollPane.setVvalue(1.0);
                        scene.getRoot().applyCss();
                        scene.getRoot().layout();

                        M3ListItem lastItem = lastDemoSidebarItem(scene.getRoot());
                        return "Scrims".equals(lastItem.getHeadlineText())
                                && nodeInsideNearestScrollViewport(lastItem, CONTROL_EDGE_TOLERANCE);
                    },
                    SETTLED_STATE_PULSES,
                    () -> "Timed out waiting for the fully expanded demo sidebar to reveal its last item: "
                            + sidebarScrollDebug(sceneReference.get()),
                    () -> {
                        M3FXDemoApp app = Objects.requireNonNull(appReference.get(), "app");
                        Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
                        app.showPageByTitle("Components Overview");
                        scene.getRoot().applyCss();
                        scene.getRoot().layout();
                        for (M3NavigationDrawerGroup group : demoSidebarDrawerGroups(scene.getRoot())) {
                            group.setExpanded(true);
                        }
                    },
                    () -> {
                        Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
                        List<M3NavigationDrawerGroup> groups = demoSidebarDrawerGroups(scene.getRoot());
                        assertFalse(groups.isEmpty(), "demo sidebar drawer groups");
                        assertTrue(groups.stream().allMatch(M3NavigationDrawerGroup::isExpanded),
                                "all demo sidebar drawer groups should be expanded");

                        ScrollPane sidebarViewport = Objects.requireNonNull(
                                demoSidebarViewport(scene.getRoot()),
                                "demo sidebar viewport"
                        );
                        assertEquals(1.0, sidebarViewport.getVvalue(), 0.001,
                                "fully expanded sidebar should support scrolling to the bottom");
                        assertTrue(M3ScrollPane.isSmoothScrollingEnabled(sidebarViewport),
                                "demo sidebar should delegate wheel input to its Material viewport");
                        Node sidebarContent = Objects.requireNonNull(
                                sidebarViewport.getContent(),
                                "demo sidebar viewport content"
                        );
                        assertTrue(sidebarContent.getLayoutBounds().getHeight()
                                        > sidebarViewport.getViewportBounds().getHeight(),
                                "the Material viewport should own the expanded sidebar scroll range");
                        M3NavigationDrawer sidebarDrawer = assertInstanceOf(
                                M3NavigationDrawer.class,
                                requireVisibleStyledDescendant(
                                        scene.getRoot(),
                                        "demo-sidebar-drawer",
                                        "demo sidebar drawer"
                                )
                        );
                        assertSame(
                                sidebarViewport,
                                sidebarDrawer.lookup(".m3-navigation-drawer-viewport"),
                                "the drawer should own the only sidebar scroll viewport"
                        );

                        M3ListItem lastItem = lastDemoSidebarItem(scene.getRoot());
                        assertEquals("Scrims", lastItem.getHeadlineText(), "last fully expanded sidebar destination");
                        assertNodeInsideNearestScrollViewport(lastItem, "last fully expanded sidebar destination");

                        WritableImage image = snapshot(scene);
                        writeVisualSnapshot(image, Path.of(
                                "build",
                                "reports",
                                "m3fx-demo-visual",
                                "sidebar-all-expanded-bottom-scroll.png"
                        ));
                        assertSnapshotHasVisibleContent(image, "Sidebar all-expanded bottom scroll");
                    }
            );
        } finally {
            FxTestUtils.runOnFxThread(() -> {
                Stage stage = stageReference.get();
                if (stage != null) {
                    stage.close();
                }
            });
        }
    }

    /// Verifies mouse-wheel scrolling can reach the final destination while drawer groups are still expanding.
    @Test
    void sidebarWheelScrollingCanReachLastDestinationDuringGroupExpansion() throws InterruptedException {
        AtomicReference<@Nullable Stage> stageReference = new AtomicReference<>();
        AtomicReference<@Nullable M3FXDemoApp> appReference = new AtomicReference<>();
        AtomicReference<@Nullable Scene> sceneReference = new AtomicReference<>();

        FxTestUtils.runOnFxThread(() -> {
            Stage stage = new Stage();
            M3FXDemoApp app = new M3FXDemoApp();
            app.start(stage);
            stage.setWidth(1280.0);
            stage.setHeight(720.0);

            stageReference.set(stage);
            appReference.set(app);
            sceneReference.set(Objects.requireNonNull(app.activeScene(), "scene"));
        });

        try {
            FxTestUtils.runOnFxThreadWhenStable(
                    () -> {
                        Scene scene = sceneReference.get();
                        if (scene == null) {
                            return false;
                        }
                        scene.getRoot().applyCss();
                        scene.getRoot().layout();

                        @Nullable ScrollPane scrollPane = demoSidebarViewport(scene.getRoot());
                        if (scrollPane == null) {
                            return false;
                        }

                        if (scrollPane.getVvalue() < 0.98) {
                            @Nullable M3ListItem eventTarget = firstVisibleUnselectedSidebarItemInSceneViewport(
                                    scene.getRoot()
                            );
                            if (eventTarget != null) {
                                for (int i = 0; i < 4; i++) {
                                    fireVerticalWheelScroll(eventTarget, -720.0);
                                }
                            }
                        }

                        List<M3NavigationDrawerGroup> groups = demoSidebarDrawerGroups(scene.getRoot());
                        if (groups.isEmpty() || groups.stream().anyMatch(group -> !group.isExpanded())) {
                            return false;
                        }
                        M3ListItem lastItem = lastDemoSidebarItem(scene.getRoot());
                        return scrollPane.getVvalue() > 0.95
                                && "Scrims".equals(lastItem.getHeadlineText())
                                && nodeInsideNearestScrollViewport(lastItem, CONTROL_EDGE_TOLERANCE);
                    },
                    SETTLED_STATE_PULSES,
                    () -> "Timed out waiting for wheel scrolling during sidebar expansion to reveal the final item: "
                            + sidebarScrollDebug(sceneReference.get()),
                    () -> {
                        M3FXDemoApp app = Objects.requireNonNull(appReference.get(), "app");
                        Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
                        app.showPageByTitle("Components Overview");
                        scene.getRoot().applyCss();
                        scene.getRoot().layout();

                        ScrollPane sidebarViewport = Objects.requireNonNull(
                                demoSidebarViewport(scene.getRoot()),
                                "demo sidebar viewport"
                        );
                        sidebarViewport.setVvalue(0.0);

                        List<M3NavigationDrawerGroup> groups = demoSidebarDrawerGroups(scene.getRoot());
                        assertFalse(groups.isEmpty(), "demo sidebar drawer groups");
                        for (M3NavigationDrawerGroup group : groups) {
                            group.setExpanded(false);
                        }
                        scene.getRoot().applyCss();
                        scene.getRoot().layout();
                        for (M3NavigationDrawerGroup group : groups) {
                            group.setExpanded(true);
                        }

                        M3ListItem eventTarget = Objects.requireNonNull(
                                firstVisibleUnselectedSidebarItemInSceneViewport(scene.getRoot()),
                                "demo sidebar expansion wheel target"
                        );
                        for (int i = 0; i < 4; i++) {
                            fireVerticalWheelScroll(eventTarget, -720.0);
                        }
                    },
                    () -> {
                        Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
                        ScrollPane sidebarViewport = Objects.requireNonNull(
                                demoSidebarViewport(scene.getRoot()),
                                "demo sidebar viewport"
                        );
                        assertTrue(sidebarViewport.getVvalue() > 0.95,
                                () -> "wheel scrolling during expansion should move the sidebar near the bottom: "
                                        + sidebarScrollDebug(scene));

                        M3ListItem lastItem = lastDemoSidebarItem(scene.getRoot());
                        assertEquals("Scrims", lastItem.getHeadlineText(),
                                "last expansion-scrolled sidebar destination");
                        assertNodeInsideNearestScrollViewport(lastItem,
                                "last expansion-scrolled sidebar destination");

                        WritableImage image = snapshot(scene);
                        writeVisualSnapshot(image, Path.of(
                                "build",
                                "reports",
                                "m3fx-demo-visual",
                                "sidebar-expanding-wheel-bottom-scroll.png"
                        ));
                        assertSnapshotHasVisibleContent(image, "Sidebar expanding wheel bottom scroll");
                    }
            );
        } finally {
            FxTestUtils.runOnFxThread(() -> {
                Stage stage = stageReference.get();
                if (stage != null) {
                    stage.close();
                }
            });
        }
    }

