    /// Verifies that a target's ripple release includes a visible intermediate fade-out frame.
    private static void verifyRippleReleaseAnimation(
            AtomicReference<@Nullable M3FXDemoApp> appReference,
            AtomicReference<@Nullable Scene> sceneReference,
            @Nullable String pageTitle,
            String snapshotName,
            String targetName,
            Function<Node, @Nullable Node> targetLookup
    ) throws InterruptedException {
        AtomicReference<@Nullable Node> targetReference = new AtomicReference<>();
        AtomicReference<@Nullable Node> rippleReference = new AtomicReference<>();
        AtomicReference<@Nullable Bounds> targetBoundsReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> normalReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> pressedReference = new AtomicReference<>();
        AtomicReference<@Nullable Double> releaseStartOpacityReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> releaseStartReference = new AtomicReference<>();
        AtomicReference<@Nullable Double> releaseOpacityReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> releaseReference = new AtomicReference<>();
        AtomicReference<@Nullable Double> settledOpacityReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> settledReference = new AtomicReference<>();

        runOnFxThreadWhenNodeAreaChanged(targetReference, normalReference, sceneReference, pressedReference, () -> {
            M3FXDemoApp app = Objects.requireNonNull(appReference.get(), "app");
            Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
            FxTestUtils.setMotionScheme(scene.getRoot(), visualRippleMotionScheme());
            if (pageTitle != null) {
                app.showPageByTitle(pageTitle);
            }
            scene.getRoot().applyCss();
            scene.getRoot().layout();

            Node lookupRoot = pageTitle == null ? scene.getRoot() : currentDemoPage(scene, pageTitle);
            Node target = Objects.requireNonNull(targetLookup.apply(lookupRoot), targetName);
            scrollAncestorScrollPanesNodeIntoView(target);
            scene.getRoot().applyCss();
            scene.getRoot().layout();
            targetReference.set(target);
            targetBoundsReference.set(nodeAreaBounds(target));
            normalReference.set(snapshot(scene));
            writeInteractionSnapshot(
                    Objects.requireNonNull(normalReference.get(), "normal ripple target snapshot"),
                    snapshotName,
                    "normal"
            );
            firePrimaryMouseEvent(target, MouseEvent.MOUSE_PRESSED, true);
            scene.getRoot().applyCss();
            scene.getRoot().layout();
            if (target instanceof ButtonBase button) {
                assertTrue(button.isArmed(), () -> targetName + " should arm on a primary press; modalBlocked="
                        + M3ModalInteraction.isBlocked(target));
            }
            Node ripple = Objects.requireNonNull(
                    target.lookup("." + RIPPLE_STYLE_CLASS),
                    targetName + " ripple node after press"
            );
            assertTrue(ripple.getOpacity() > 0.0, targetName + " ripple should become visible on press");
        }, () -> {
            writeInteractionSnapshot(
                    Objects.requireNonNull(pressedReference.get(), "pressed ripple target snapshot"),
                    snapshotName,
                    "pressed"
            );
            Node target = Objects.requireNonNull(targetReference.get(), targetName);
            releasePrimaryMouseWithoutAction(target);
            Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
            Node ripple = Objects.requireNonNull(
                    target.lookup("." + RIPPLE_STYLE_CLASS),
                    targetName + " ripple node"
            );
            rippleReference.set(ripple);
            releaseStartOpacityReference.set(ripple.getOpacity());
            releaseStartReference.set(snapshot(scene));
        });

        FxTestUtils.runOnFxThreadWhen(() -> {
            @Nullable Node target = targetReference.get();
            @Nullable Node ripple = rippleReference.get();
            @Nullable Double releaseStartOpacity = releaseStartOpacityReference.get();
            @Nullable WritableImage releaseStart = releaseStartReference.get();
            @Nullable Scene scene = sceneReference.get();
            if (target == null
                    || ripple == null
                    || releaseStartOpacity == null
                    || ripple.getOpacity() <= 0.02
                    || ripple.getOpacity() >= releaseStartOpacity * 0.92
                    || releaseStart == null
                    || scene == null) {
                return false;
            }

            if (!captureSceneFrameWithChangedNodeArea(target, releaseStart, scene, releaseReference)) {
                return false;
            }

            releaseOpacityReference.set(ripple.getOpacity());
            return true;
        }, () -> {
        }, () -> {
            writeInteractionSnapshot(
                    Objects.requireNonNull(releaseReference.get(), "released ripple target snapshot"),
                    snapshotName,
                    "released"
            );
        });

        runOnFxThreadWhenNodeAreaStable(targetReference, sceneReference, settledReference, () -> {
            @Nullable Node ripple = rippleReference.get();
            return ripple != null && ripple.getOpacity() <= 0.001;
        }, () -> {
        }, () -> {
            Node ripple = Objects.requireNonNull(rippleReference.get(), targetName + " ripple node");
            settledOpacityReference.set(ripple.getOpacity());
            writeInteractionSnapshot(
                    Objects.requireNonNull(settledReference.get(), "settled ripple target snapshot"),
                    snapshotName,
                    "settled"
            );
        });

        Bounds targetBounds = Objects.requireNonNull(targetBoundsReference.get(), targetName + " bounds");
        assertNodeAreaChanged(
                targetBounds,
                Objects.requireNonNull(normalReference.get(), "normal ripple target snapshot"),
                Objects.requireNonNull(pressedReference.get(), "pressed ripple target snapshot"),
                targetName + " ripple pressed frame"
        );
        assertNodeAreaChanged(
                targetBounds,
                Objects.requireNonNull(releaseStartReference.get(), "release-start ripple target snapshot"),
                Objects.requireNonNull(releaseReference.get(), "released ripple target snapshot"),
                targetName + " ripple release intermediate frame"
        );
        assertRippleOpacityFaded(
                Objects.requireNonNull(releaseOpacityReference.get(), "released ripple opacity"),
                Objects.requireNonNull(settledOpacityReference.get(), "settled ripple opacity"),
                targetName + " ripple release fade-out"
        );
        Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
        FxTestUtils.clearMotionScheme(scene.getRoot());
    }

    /// Returns the first visible text-input layout whose built-in clear button is active.
    private static @Nullable M3TextInputLayout firstTextInputClearButtonLayout(Node root) {
        for (M3TextInputLayout layout : visibleNodesOfType(root, M3TextInputLayout.class)) {
            @Nullable TextInputControl input = layout.getInput();
            if (layout.isClearButtonEnabled()
                    && input != null
                    && !input.getText().isEmpty()
                    && firstVisibleStyledDescendant(layout, "m3-text-input-clear-button") != null) {
                return layout;
            }
        }
        return null;
    }

    /// Returns the first visible password-field trailing action button.
    private static @Nullable Node firstTextInputTrailingActionButton(Node root) {
        for (M3TextInputLayout layout : visibleNodesOfType(root, M3TextInputLayout.class)) {
            if (layout.getInput() instanceof M3PasswordField
                    && layout.getTrailing() instanceof M3IconButton button
                    && button.isVisible()
                    && hasRenderableBounds(button)) {
                return button;
            }
        }
        return null;
    }

    /// Hides every showing picker field below a root.
    private static void hideShowingPickerFields(Node root) {
        visitVisibleNodes(root, node -> {
            if (node instanceof M3PickerField<?, ?> field && field.isShowing()) {
                field.hidePicker();
            }
        });
    }

    /// Hides every showing menu button below a root.
    private static void hideShowingMenuButtons(Node root) {
        visitVisibleNodes(root, node -> {
            if (node instanceof M3MenuButton menuButton && menuButton.isShowing()) {
                menuButton.hideMenu();
            }
        });
    }

    /// Dismisses every snackbar presented by an overlay pane below a root.
    private static void hideShowingSnackbars(Node root) {
        visitVisibleNodes(root, node -> {
            if (node instanceof M3OverlayPane overlay && overlay.isSnackbarShowing()) {
                overlay.dismissAllSnackbars();
            }
        });
    }

    /// Returns a ripple-specific motion scheme that makes release fade frames observable in real snapshots.
    private static M3MotionScheme visualRippleMotionScheme() {
        M3MotionScheme standard = M3MotionScheme.standard();
        M3MotionSpec observableSpec = M3MotionSpec.of(OBSERVABLE_MOTION_DURATION, M3MotionEasing.LINEAR);
        return M3MotionScheme.builder(standard)
                .defaultEffects(observableSpec)
                .defaultSpatial(observableSpec)
                .build();
    }

    /// Verifies that switch selection produces visible thumb animation intermediate frames.
    private static void verifySwitchSelectionAnimation(
            AtomicReference<@Nullable M3FXDemoApp> appReference,
            AtomicReference<@Nullable Scene> sceneReference
    ) throws InterruptedException {
        AtomicReference<@Nullable M3Switch> targetReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> normalReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> intermediateReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> settledReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> focusedReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> draggedReference = new AtomicReference<>();

        runOnFxThreadWhenNodeAreaChanged(targetReference, normalReference, sceneReference, intermediateReference, () -> {
            M3FXDemoApp app = Objects.requireNonNull(appReference.get(), "app");
            Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
            app.showPageByTitle("Switches");
            scene.getRoot().applyCss();
            scene.getRoot().layout();

            M3Switch target = Objects.requireNonNull(firstVisibleSwitchWithText(
                    scene.getRoot(),
                    "Off"
            ), "switch");
            FxTestUtils.setMotionScheme(target, visualSwitchMotionScheme());
            targetReference.set(target);
            normalReference.set(snapshot(scene));
            writeInteractionSnapshot(
                    Objects.requireNonNull(normalReference.get(), "normal switch snapshot"),
                    "switch-selection",
                    "normal"
            );
            target.fire();
            scene.getRoot().applyCss();
            scene.getRoot().layout();
            assertTrue(target.isSelected());
        }, () -> {
            writeInteractionSnapshot(
                    Objects.requireNonNull(intermediateReference.get(), "intermediate switch snapshot"),
                    "switch-selection",
                    "intermediate"
            );
        });

        runOnFxThreadWhenNodeAreaStable(targetReference, sceneReference, settledReference, () -> {
            @Nullable M3Switch target = targetReference.get();
            return target != null && target.isSelected();
        }, () -> {
        }, () -> {
            writeInteractionSnapshot(
                    Objects.requireNonNull(settledReference.get(), "settled switch snapshot"),
                    "switch-selection",
                    "settled"
            );
            FxTestUtils.clearMotionScheme(Objects.requireNonNull(targetReference.get(), "switch"));
        });

        M3Switch target = Objects.requireNonNull(targetReference.get(), "switch");
        assertNodeAreaChanged(
                target,
                Objects.requireNonNull(normalReference.get(), "normal switch snapshot"),
                Objects.requireNonNull(intermediateReference.get(), "intermediate switch snapshot"),
                "switch selection intermediate frame"
        );
        assertNodeAreaChanged(
                target,
                Objects.requireNonNull(intermediateReference.get(), "intermediate switch snapshot"),
                Objects.requireNonNull(settledReference.get(), "settled switch snapshot"),
                "switch selection settling frame"
        );

        runOnFxThreadWhenNodeAreaChanged(targetReference, settledReference, sceneReference, focusedReference, () -> {
            M3MotionSettings.setReducedMotionRequested(target, true);
            target.pseudoClassStateChanged(PseudoClass.getPseudoClass("focus-visible"), true);
        }, () -> {
            WritableImage focused = Objects.requireNonNull(focusedReference.get(), "focused switch snapshot");
            writeInteractionSnapshot(focused, "switch-selection", "focused");
            assertSwitchFocusIndicatorSurroundsTrack(target);
        });

        runOnFxThreadWhenNodeAreaStable(targetReference, sceneReference, draggedReference, target::isArmed, () -> {
            target.pseudoClassStateChanged(PseudoClass.getPseudoClass("focus-visible"), false);
            M3MotionSettings.setReducedMotionRequested(target, false);
            Node track = Objects.requireNonNull(target.lookup(".m3-switch-track"), "switch track");
            fireSwitchTrackMouseEventAtPosition(track, MouseEvent.MOUSE_PRESSED, 1.0, true);
            fireSwitchTrackMouseEventAtPosition(track, MouseEvent.MOUSE_DRAGGED, 0.0, true);
            Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
            scene.getRoot().applyCss();
            scene.getRoot().layout();
        }, () -> {
            WritableImage dragged = Objects.requireNonNull(draggedReference.get(), "dragged switch snapshot");
            writeInteractionSnapshot(dragged, "switch-selection", "dragged-off");
            assertTrue(target.isSelected(), "Switch selection should remain committed until the drag is released");
            assertSwitchThumbAtOffSide(target);
            Node thumb = Objects.requireNonNull(target.lookup(".m3-switch-thumb"), "switch thumb");
            Bounds thumbBounds = thumb.localToScene(thumb.getBoundsInLocal());
            assertEquals(target.getPressedHandleSize(), thumbBounds.getWidth(), CONTROL_EDGE_TOLERANCE,
                    "A dragged switch should use its pressed handle-size token");
            assertEquals(target.getPressedHandleSize(), thumbBounds.getHeight(), CONTROL_EDGE_TOLERANCE,
                    "A dragged switch should keep the pressed handle circular");

            Node track = Objects.requireNonNull(target.lookup(".m3-switch-track"), "switch track");
            fireSwitchTrackMouseEventAtPosition(track, MouseEvent.MOUSE_RELEASED, 0.0, false);
            assertFalse(target.isSelected(), "Releasing a handle drag at the off side should clear selection");
            FxTestUtils.clearMotionScheme(target);
        });

        assertNodeAreaChanged(
                target,
                Objects.requireNonNull(settledReference.get(), "settled switch snapshot"),
                Objects.requireNonNull(focusedReference.get(), "focused switch snapshot"),
                "switch full-track focus indicator"
        );
        assertNodeAreaChanged(
                target,
                Objects.requireNonNull(focusedReference.get(), "focused switch snapshot"),
                Objects.requireNonNull(draggedReference.get(), "dragged switch snapshot"),
                "switch direct handle drag"
        );
    }

    /// Verifies that a horizontal slider responds to real pointer press, drag, release, and settling.
    private static void verifySliderDragInteraction(
            AtomicReference<@Nullable M3FXDemoApp> appReference,
            AtomicReference<@Nullable Scene> sceneReference
    ) throws InterruptedException {
        AtomicReference<@Nullable M3Slider> targetReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> normalReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> pressedReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> draggedReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> settledReference = new AtomicReference<>();
        AtomicReference<@Nullable Double> initialValueReference = new AtomicReference<>();
        AtomicReference<@Nullable Double> draggedValueReference = new AtomicReference<>();

        runOnFxThreadWhenNodeAreaChanged(targetReference, normalReference, sceneReference, pressedReference, () -> {
            M3FXDemoApp app = Objects.requireNonNull(appReference.get(), "app");
            Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
            app.showPageByTitle("Sliders");
            scene.getRoot().applyCss();
            scene.getRoot().layout();

            M3Slider target = Objects.requireNonNull(firstInteractiveHorizontalSlider(scene.getRoot()), "slider");
            targetReference.set(target);
            initialValueReference.set(target.getValue());
            normalReference.set(snapshot(scene));
            writeInteractionSnapshot(
                    Objects.requireNonNull(normalReference.get(), "normal slider snapshot"),
                    "slider-drag",
                    "normal"
            );

            M3MotionSettings.setReducedMotionRequested(target, true);
            target.pseudoClassStateChanged(PseudoClass.getPseudoClass("focus-visible"), true);
            scene.getRoot().applyCss();
            scene.getRoot().layout();
            Node focusIndicator = Objects.requireNonNull(
                    target.lookup(".m3-focus-indicator"),
                    "slider focus indicator"
            );
            Node thumb = Objects.requireNonNull(target.lookup(".thumb"), "slider thumb");
            Bounds focusBounds = focusIndicator.localToScene(focusIndicator.getBoundsInLocal());
            Bounds thumbBounds = thumb.localToScene(thumb.getBoundsInLocal());
            assertTrue(focusIndicator.isVisible(), "Keyboard-visible slider focus should render an indicator");
            assertTrue(focusBounds.getMinX() <= thumbBounds.getMinX() + CONTROL_EDGE_TOLERANCE
                            && focusBounds.getMaxX() >= thumbBounds.getMaxX() - CONTROL_EDGE_TOLERANCE
                            && focusBounds.getMinY() <= thumbBounds.getMinY() + CONTROL_EDGE_TOLERANCE
                            && focusBounds.getMaxY() >= thumbBounds.getMaxY() - CONTROL_EDGE_TOLERANCE,
                    "Slider focus indicator should surround the visible handle");
            assertTrue(focusBounds.getWidth() < target.getTouchTargetSize(),
                    "Slider focus indicator should not outline the circular touch target");
            writeInteractionSnapshot(snapshot(scene), "slider-drag", "focused");
            target.pseudoClassStateChanged(PseudoClass.getPseudoClass("focus-visible"), false);
            M3MotionSettings.setReducedMotionRequested(target, false);
            scene.getRoot().applyCss();
            scene.getRoot().layout();

            fireSliderMouseEventAtPosition(target, MouseEvent.MOUSE_PRESSED, normalizedSliderPosition(target), true);
            scene.getRoot().applyCss();
            scene.getRoot().layout();
            assertTrue(target.isValueChanging(), "slider should enter value-changing state after mouse press");
        }, () -> {
            writeInteractionSnapshot(
                    Objects.requireNonNull(pressedReference.get(), "pressed slider snapshot"),
                    "slider-drag",
                    "pressed"
            );
            M3Slider target = Objects.requireNonNull(targetReference.get(), "slider");
            Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
            fireSliderMouseEventAtPosition(target, MouseEvent.MOUSE_DRAGGED, 0.82, true);
            scene.getRoot().applyCss();
            scene.getRoot().layout();
            draggedValueReference.set(target.getValue());
            assertTrue(target.isValueChanging(), "slider should remain value-changing while dragged");
            assertTrue(target.getValue() > Objects.requireNonNull(initialValueReference.get(), "initial slider value"),
                    "slider drag should increase the value");
        });

        runOnFxThreadWhenNodeAreaChanged(targetReference, pressedReference, sceneReference, draggedReference, () -> {
        }, () -> {
            writeInteractionSnapshot(
                    Objects.requireNonNull(draggedReference.get(), "dragged slider snapshot"),
                    "slider-drag",
                    "dragged"
            );
            M3Slider target = Objects.requireNonNull(targetReference.get(), "slider");
            Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
            fireSliderMouseEventAtPosition(target, MouseEvent.MOUSE_RELEASED, 0.82, false);
            scene.getRoot().applyCss();
            scene.getRoot().layout();
            assertFalse(target.isValueChanging(), "slider should leave value-changing state after mouse release");
        });

        runOnFxThreadWhenNodeAreaStable(targetReference, sceneReference, settledReference, () -> {
            @Nullable M3Slider target = targetReference.get();
            @Nullable Double draggedValue = draggedValueReference.get();
            return target != null
                    && draggedValue != null
                    && !target.isValueChanging()
                    && Math.abs(target.getValue() - draggedValue) <= 0.001;
        }, () -> {
        }, () -> {
            writeInteractionSnapshot(
                    Objects.requireNonNull(settledReference.get(), "settled slider snapshot"),
                    "slider-drag",
                    "settled"
            );
        });

        M3Slider target = Objects.requireNonNull(targetReference.get(), "slider");
        assertNodeAreaChanged(
                target,
                Objects.requireNonNull(normalReference.get(), "normal slider snapshot"),
                Objects.requireNonNull(pressedReference.get(), "pressed slider snapshot"),
                "slider press"
        );
        assertNodeAreaChanged(
                target,
                Objects.requireNonNull(pressedReference.get(), "pressed slider snapshot"),
                Objects.requireNonNull(draggedReference.get(), "dragged slider snapshot"),
                "slider drag"
        );
        assertNodeAreaChanged(
                target,
                Objects.requireNonNull(normalReference.get(), "normal slider snapshot"),
                Objects.requireNonNull(settledReference.get(), "settled slider snapshot"),
                "slider settled value"
        );
    }

    /// Returns a switch-specific motion scheme that makes real visual intermediate frames observable.
    private static M3MotionScheme visualSwitchMotionScheme() {
        M3MotionScheme standard = M3MotionScheme.standard();
        return M3MotionScheme.builder(standard)
                .fastSpatial(M3MotionSpec.of(OBSERVABLE_MOTION_DURATION, M3MotionEasing.LINEAR))
                .build();
    }

    /// Verifies popup motion together with the split button selected-state shape morph.
    private static void verifySplitButtonPopupAnimation(
            AtomicReference<@Nullable M3FXDemoApp> appReference,
            AtomicReference<@Nullable Scene> sceneReference
    ) throws InterruptedException {
        AtomicReference<@Nullable M3SplitButton> targetReference = new AtomicReference<>();
        AtomicReference<@Nullable Node> popupRootReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> openingBaselineReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> openingReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> settledReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> hidingReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> closedButtonReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> openingButtonReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> settledButtonReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> hidingButtonReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> closedAgainButtonReference = new AtomicReference<>();

        runOnFxThreadWhenNodeSnapshotChanged(
                popupRootReference::get,
                openingBaselineReference,
                openingReference,
                "split button popup opening frame",
                () -> {
                    M3FXDemoApp app = Objects.requireNonNull(appReference.get(), "app");
                    Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
                    app.showPageByTitle("Split Buttons");
                    scene.getRoot().applyCss();
                    scene.getRoot().layout();

                    M3SplitButton target = Objects.requireNonNull(firstVisibleSplitButtonWithText(
                            scene.getRoot(),
                            "Create"
                    ), "split button");
                    M3MotionScheme standard = M3MotionScheme.standard();
                    M3MotionSpec observableSpec =
                            M3MotionSpec.of(OBSERVABLE_MOTION_DURATION, M3MotionEasing.LINEAR);
                    FxTestUtils.setMotionScheme(target, M3MotionScheme.builder(standard)
                            .defaultEffects(observableSpec)
                            .fastSpatial(observableSpec)
                            .defaultSpatial(observableSpec)
                            .build());
                    closedButtonReference.set(snapshotNode(target));
                    target.showMenu();
                    assertTrue(target.isShowing());

                    Node popupRoot = target.getMenu();
                    layoutPopupRoot(popupRoot);
                    targetReference.set(target);
                    popupRootReference.set(popupRoot);
                    openingBaselineReference.set(snapshotNode(popupRoot));
                }, () -> {
                    writeAnimationSnapshot(
                            Objects.requireNonNull(openingReference.get(), "opening split button popup snapshot"),
                            "split-button-popup",
                            "opening"
                    );
                });

        runOnFxThreadWhenNodeSnapshotChanged(
                targetReference::get,
                closedButtonReference,
                openingButtonReference,
                "split button opening shape frame",
                () -> {
                }, () -> writeAnimationSnapshot(
                        Objects.requireNonNull(openingButtonReference.get(), "opening split button snapshot"),
                        "split-button-shape",
                        "opening"
                ));

        runOnFxThreadWhenNodeSnapshotStable(
                popupRootReference::get,
                settledReference,
                () -> popupRootSettled(popupRootReference.get()),
                "split button popup settled frame",
                () -> {
                }, () -> {
                    M3SplitButton target = Objects.requireNonNull(targetReference.get(), "split button");
                    assertTrue(target.isShowing());
                    Node popupRoot = Objects.requireNonNull(popupRootReference.get(), "split button popup");
                    layoutPopupRoot(popupRoot);
                    writeAnimationSnapshot(
                            Objects.requireNonNull(settledReference.get(), "settled split button popup snapshot"),
                            "split-button-popup",
                            "settled"
                    );
                    assertSnapshotHasVisibleContent(
                            Objects.requireNonNull(settledReference.get(), "settled split button popup snapshot"),
                            "split button popup"
                    );
                    WritableImage buttonSnapshot = snapshotNode(target);
                    settledButtonReference.set(buttonSnapshot);
                    writeAnimationSnapshot(buttonSnapshot, "split-button-shape", "selected");
                    target.hideMenu();
                });

        runOnFxThreadWhenNodeSnapshotChanged(
                popupRootReference::get,
                settledReference,
                hidingReference,
                "split button popup hiding frame",
                () -> {
                }, () -> writeAnimationSnapshot(
                        Objects.requireNonNull(hidingReference.get(), "hiding split button popup snapshot"),
                        "split-button-popup",
                        "hiding"
                ));

        runOnFxThreadWhenNodeSnapshotChanged(
                targetReference::get,
                settledButtonReference,
                hidingButtonReference,
                "split button closing shape frame",
                () -> {
                }, () -> writeAnimationSnapshot(
                        Objects.requireNonNull(hidingButtonReference.get(), "hiding split button snapshot"),
                        "split-button-shape",
                        "hiding"
                ));

        FxTestUtils.runOnFxThreadWhenStable(() -> {
            @Nullable M3SplitButton target = targetReference.get();
            return target != null && !target.isShowing();
        }, SETTLED_STATE_PULSES, () -> {
        }, () -> {
            M3SplitButton target = Objects.requireNonNull(targetReference.get(), "split button");
            assertFalse(target.isShowing());
            WritableImage buttonSnapshot = snapshotNode(target);
            closedAgainButtonReference.set(buttonSnapshot);
            writeAnimationSnapshot(buttonSnapshot, "split-button-shape", "closed");
            FxTestUtils.clearMotionScheme(target);
        });

        assertSnapshotChanged(
                Objects.requireNonNull(closedButtonReference.get(), "closed split button snapshot"),
                Objects.requireNonNull(openingButtonReference.get(), "opening split button snapshot"),
                "split button opening shape morph"
        );
        assertSnapshotChanged(
                Objects.requireNonNull(openingButtonReference.get(), "opening split button snapshot"),
                Objects.requireNonNull(settledButtonReference.get(), "selected split button snapshot"),
                "split button selected shape settle"
        );
        assertSnapshotChanged(
                Objects.requireNonNull(settledButtonReference.get(), "selected split button snapshot"),
                Objects.requireNonNull(hidingButtonReference.get(), "hiding split button snapshot"),
                "split button closing shape morph"
        );
        assertSnapshotChanged(
                Objects.requireNonNull(hidingButtonReference.get(), "hiding split button snapshot"),
                Objects.requireNonNull(closedAgainButtonReference.get(), "closed-again split button snapshot"),
                "split button closed shape settle"
        );
        assertSnapshotChanged(
                Objects.requireNonNull(openingReference.get(), "opening split button popup snapshot"),
                Objects.requireNonNull(settledReference.get(), "settled split button popup snapshot"),
                "split button popup enter motion"
        );
        assertSnapshotChanged(
                Objects.requireNonNull(settledReference.get(), "settled split button popup snapshot"),
                Objects.requireNonNull(hidingReference.get(), "hiding split button popup snapshot"),
                "split button popup exit motion"
        );
    }

    /// Verifies nested menu popup enter and exit motion with side-by-side popup placement.
    private static void verifyNestedMenuPopupStackAnimation(
            AtomicReference<@Nullable M3FXDemoApp> appReference,
            AtomicReference<@Nullable Scene> sceneReference
    ) throws InterruptedException {
        AtomicReference<@Nullable M3MenuButton> menuButtonReference = new AtomicReference<>();
        AtomicReference<@Nullable M3SubMenuItem> subMenuItemReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> ownerMenuReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> openingBaselineReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> openingReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> settledReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> hidingReference = new AtomicReference<>();

        FxTestUtils.runOnFxThreadWhenStable(() -> {
            @Nullable M3MenuButton menuButton = menuButtonReference.get();
            return menuButton != null
                    && menuButton.isShowing()
                    && menuButton.getMenu().getScene() != null;
        }, SETTLED_STATE_PULSES, () -> {
            M3FXDemoApp app = Objects.requireNonNull(appReference.get(), "app");
            Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
            app.showPageByTitle("Menus");
            scene.getRoot().applyCss();
            scene.getRoot().layout();

            M3MenuButton menuButton = Objects.requireNonNull(firstVisibleMenuButtonWithText(
                    scene.getRoot(),
                    "Open menu"
            ), "menu button");
            FxTestUtils.setMotionScheme(menuButton, visualPopupMotionScheme());
            menuButton.showMenu();
            assertTrue(menuButton.isShowing());
            menuButtonReference.set(menuButton);
        }, () -> {
            M3MenuButton menuButton = Objects.requireNonNull(menuButtonReference.get(), "menu button");
            layoutPopupRoot(menuButton.getMenu());
        });

        runOnFxThreadWhenNodeSnapshotStable(() -> {
            @Nullable M3MenuButton menuButton = menuButtonReference.get();
            return menuButton == null ? null : menuButton.getMenu();
        }, ownerMenuReference, () -> {
            @Nullable M3MenuButton menuButton = menuButtonReference.get();
            return menuButton != null && popupRootSettled(menuButton.getMenu());
        }, "nested owner menu settled frame", () -> {
        }, () -> {
            M3MenuButton menuButton = Objects.requireNonNull(menuButtonReference.get(), "menu button");
            assertTrue(menuButton.isShowing());
            layoutPopupRoot(menuButton.getMenu());
            writeAnimationSnapshot(
                    Objects.requireNonNull(ownerMenuReference.get(), "owner menu snapshot"),
                    "nested-menu-owner",
                    "settled"
            );

            M3SubMenuItem subMenuItem = Objects.requireNonNull(firstVisibleSubMenuItemWithText(
                    menuButton.getMenu(),
                    "Move to"
            ), "submenu item");
            FxTestUtils.setMotionScheme(subMenuItem, visualPopupMotionScheme());
            subMenuItem.showSubMenu();
            assertTrue(subMenuItem.isSubMenuShowing());
            layoutPopupRoot(subMenuItem.getSubMenu());
            openingBaselineReference.set(snapshotNode(subMenuItem.getSubMenu()));
            subMenuItemReference.set(subMenuItem);
        });

        runOnFxThreadWhenNodeSnapshotChanged(
                () -> {
                    @Nullable M3SubMenuItem subMenuItem = subMenuItemReference.get();
                    return subMenuItem == null ? null : subMenuItem.getSubMenu();
                },
                openingBaselineReference,
                openingReference,
                "nested submenu opening frame",
                () -> {
                }, () -> {
                    writeAnimationSnapshot(
                            Objects.requireNonNull(openingReference.get(), "opening submenu snapshot"),
                            "nested-submenu",
                            "opening"
                    );
                });

        runOnFxThreadWhenNodeSnapshotStable(() -> {
            @Nullable M3SubMenuItem subMenuItem = subMenuItemReference.get();
            return subMenuItem == null ? null : subMenuItem.getSubMenu();
        }, settledReference, () -> {
            @Nullable M3SubMenuItem subMenuItem = subMenuItemReference.get();
            return subMenuItem != null && popupRootSettled(subMenuItem.getSubMenu());
        }, "nested submenu settled frame", () -> {
        }, () -> {
            Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
            M3MenuButton menuButton = Objects.requireNonNull(menuButtonReference.get(), "menu button");
            M3SubMenuItem subMenuItem = Objects.requireNonNull(subMenuItemReference.get(), "submenu item");
            assertTrue(menuButton.isShowing());
            assertTrue(subMenuItem.isSubMenuShowing());
            layoutPopupRoot(menuButton.getMenu());
            layoutPopupRoot(subMenuItem.getSubMenu());
            assertPopupThemeContext(scene.getRoot(), menuButton.getMenu(), "owner menu");
            assertPopupThemeContext(scene.getRoot(), subMenuItem.getSubMenu(), "nested submenu");
            assertMenuSurfaceGeometry(menuButton.getMenu(), null, "nested owner menu");
            assertMenuSurfaceGeometry(subMenuItem.getSubMenu(), null, "nested submenu");
            writeAnimationSnapshot(
                    Objects.requireNonNull(settledReference.get(), "settled submenu snapshot"),
                    "nested-submenu",
                    "settled"
            );
            assertSnapshotHasVisibleContent(
                    Objects.requireNonNull(ownerMenuReference.get(), "owner menu snapshot"),
                    "nested owner menu"
            );
            assertSnapshotHasVisibleContent(
                    Objects.requireNonNull(settledReference.get(), "settled submenu snapshot"),
                    "nested submenu"
            );
            assertPopupStackSideBySide(menuButton.getMenu(), subMenuItem.getSubMenu());
            subMenuItem.hideSubMenu();
        });

        runOnFxThreadWhenNodeSnapshotChanged(
                () -> {
                    @Nullable M3SubMenuItem subMenuItem = subMenuItemReference.get();
                    return subMenuItem == null ? null : subMenuItem.getSubMenu();
                },
                settledReference,
                hidingReference,
                "nested submenu hiding frame",
                () -> {
                }, () -> {
                    writeAnimationSnapshot(
                            Objects.requireNonNull(hidingReference.get(), "hiding submenu snapshot"),
                            "nested-submenu",
                            "hiding"
                    );
                });

        FxTestUtils.runOnFxThreadWhenStable(() -> {
            @Nullable M3SubMenuItem subMenuItem = subMenuItemReference.get();
            return subMenuItem != null && !subMenuItem.isSubMenuShowing();
        }, SETTLED_STATE_PULSES, () -> {
        }, () -> {
            M3MenuButton menuButton = Objects.requireNonNull(menuButtonReference.get(), "menu button");
            M3SubMenuItem subMenuItem = Objects.requireNonNull(subMenuItemReference.get(), "submenu item");
            assertFalse(subMenuItem.isSubMenuShowing());
            menuButton.hideMenu();
            FxTestUtils.clearMotionScheme(subMenuItem);
            FxTestUtils.clearMotionScheme(menuButton);
        });

        assertSnapshotChanged(
                Objects.requireNonNull(openingReference.get(), "opening submenu snapshot"),
                Objects.requireNonNull(settledReference.get(), "settled submenu snapshot"),
                "nested submenu enter motion"
        );
        assertSnapshotChanged(
                Objects.requireNonNull(settledReference.get(), "settled submenu snapshot"),
                Objects.requireNonNull(hidingReference.get(), "hiding submenu snapshot"),
                "nested submenu exit motion"
        );
    }

