    /// Returns a popup-specific motion scheme that makes real visual intermediate frames observable.
    private static M3MotionScheme visualPopupMotionScheme() {
        M3MotionScheme standard = M3MotionScheme.standard();
        return M3MotionScheme.builder(standard)
                .fastSpatial(M3MotionSpec.of(OBSERVABLE_MOTION_DURATION, M3MotionEasing.LINEAR))
                .build();
    }

    /// Verifies selected-indicator motion on a demo navigation item.
    private static void verifyNavigationItemSelectionAnimation(
            AtomicReference<@Nullable M3FXDemoApp> appReference,
            AtomicReference<@Nullable Scene> sceneReference,
            String pageTitle,
            String snapshotName
    ) throws InterruptedException {
        AtomicReference<@Nullable M3NavigationItem> targetReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> normalReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> intermediateReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> settledReference = new AtomicReference<>();

        FxTestUtils.runOnFxThreadWhen(() -> {
            @Nullable M3NavigationItem target = targetReference.get();
            @Nullable WritableImage normal = normalReference.get();
            @Nullable Scene scene = sceneReference.get();
            if (target == null || normal == null || scene == null || !navigationIndicatorIsPartiallySelected(target)) {
                return false;
            }

            WritableImage frame = snapshot(scene);
            if (!nodeAreaChangedEnough(target, normal, frame)) {
                return false;
            }

            intermediateReference.set(frame);
            return true;
        }, () -> {
            M3FXDemoApp app = Objects.requireNonNull(appReference.get(), "app");
            Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
            app.showPageByTitle(pageTitle);
            scene.getRoot().applyCss();
            scene.getRoot().layout();

            M3NavigationItem target = Objects.requireNonNull(firstVisibleNavigationItemWithText(
                    scene.getRoot(),
                    "Search"
            ), "navigation item");
            assertFalse(target.isSelected());
            FxTestUtils.setMotionScheme(target, visualNavigationMotionScheme());
            targetReference.set(target);
            normalReference.set(snapshot(scene));
            writeAnimationSnapshot(
                    Objects.requireNonNull(normalReference.get(), "normal navigation snapshot"),
                    snapshotName,
                    "normal"
            );
            target.fire();
            scene.getRoot().applyCss();
            scene.getRoot().layout();
            assertTrue(target.isSelected());
        }, () -> {
            writeAnimationSnapshot(
                    Objects.requireNonNull(intermediateReference.get(), "intermediate navigation snapshot"),
                    snapshotName,
                    "intermediate"
            );
        });

        runOnFxThreadWhenNodeAreaStable(targetReference, sceneReference, settledReference, () -> {
            @Nullable M3NavigationItem target = targetReference.get();
            @Nullable Node indicator = target == null ? null : navigationIndicator(target);
            return target != null
                    && target.isSelected()
                    && indicator != null
                    && indicator.getOpacity() >= 0.999
                    && indicator.getScaleX() >= 0.999;
        }, () -> {
        }, () -> {
            writeAnimationSnapshot(
                    Objects.requireNonNull(settledReference.get(), "settled navigation snapshot"),
                    snapshotName,
                    "settled"
            );
            FxTestUtils.clearMotionScheme(Objects.requireNonNull(targetReference.get(), "navigation item"));
        });

        M3NavigationItem target = Objects.requireNonNull(targetReference.get(), "navigation item");
        assertNodeAreaChanged(
                target,
                Objects.requireNonNull(normalReference.get(), "normal navigation snapshot"),
                Objects.requireNonNull(intermediateReference.get(), "intermediate navigation snapshot"),
                snapshotName + " intermediate frame"
        );
        assertNodeAreaChanged(
                target,
                Objects.requireNonNull(intermediateReference.get(), "intermediate navigation snapshot"),
                Objects.requireNonNull(settledReference.get(), "settled navigation snapshot"),
                snapshotName + " settling frame"
        );
    }

    /// Returns whether the navigation selected indicator is between hidden and selected visual states.
    private static boolean navigationIndicatorIsPartiallySelected(M3NavigationItem item) {
        @Nullable Node indicator = navigationIndicator(item);
        if (indicator == null) {
            return false;
        }

        double opacity = indicator.getOpacity();
        double scaleX = indicator.getScaleX();
        return opacity > 0.05 && opacity < 0.95 && scaleX > 0.74 && scaleX < 0.99;
    }

    /// Returns the selected indicator node for a navigation item.
    private static @Nullable Node navigationIndicator(M3NavigationItem item) {
        return item.lookup(".m3-navigation-item-indicator");
    }

    /// Verifies width, header, and destination-layout motion when an expressive rail expands and collapses.
    private static void verifyNavigationRailExpansionAnimation(
            AtomicReference<@Nullable M3FXDemoApp> appReference,
            AtomicReference<@Nullable Scene> sceneReference
    ) throws InterruptedException {
        AtomicReference<@Nullable M3NavigationRail> targetReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> collapsedReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> expandingReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> expandedReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> collapsingReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> settledReference = new AtomicReference<>();

        runOnFxThreadWhenNavigationRailTransitionFrame(
                targetReference,
                expandingReference,
                "navigation rail expanding width",
                () -> {
                    M3FXDemoApp app = Objects.requireNonNull(appReference.get(), "app");
                    Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
                    app.showPageByTitle("Navigation Rail");
                    scene.getRoot().applyCss();
                    scene.getRoot().layout();

                    M3NavigationRail target = visibleNodesOfType(scene.getRoot(), M3NavigationRail.class).stream()
                            .filter(M3NavigationRail::isExpanded)
                            .filter(rail -> rail.getVariant() == M3NavigationRailVariant.STANDARD)
                            .findFirst()
                            .orElseThrow();
                    M3MotionSettings.setReducedMotionRequested(target, true);
                    target.setExpanded(false);
                    scene.getRoot().applyCss();
                    scene.getRoot().layout();
                    M3MotionSettings.setReducedMotionRequested(target, false);
                    FxTestUtils.setMotionScheme(target, visualNavigationMotionScheme());

                    targetReference.set(target);
                    collapsedReference.set(snapshotNode(target));
                    writeAnimationSnapshot(
                            Objects.requireNonNull(collapsedReference.get(), "collapsed rail snapshot"),
                            "navigation-rail-width",
                            "collapsed"
                    );
                    target.setExpanded(true);
                },
                () -> {
                    M3NavigationRail target = Objects.requireNonNull(
                            targetReference.get(),
                            "expanding navigation rail"
                    );
                    assertNavigationRailTransitionFrame(target, "expanding navigation rail");
                    writeAnimationSnapshot(
                            Objects.requireNonNull(expandingReference.get(), "expanding rail snapshot"),
                            "navigation-rail-width",
                            "expanding"
                    );
                }
        );

        runOnFxThreadWhenNodeSnapshotStable(targetReference::get, expandedReference, () -> {
            @Nullable M3NavigationRail target = targetReference.get();
            return target != null
                    && target.isExpanded()
                    && Math.abs(target.getWidth() - target.getExpandedContainerWidth()) <= CONTROL_EDGE_TOLERANCE
                    && firstNavigationRailItemLayout(target) == M3NavigationItemLayout.HORIZONTAL;
        }, "expanded navigation rail", () -> {
        }, () -> {
            M3NavigationRail target = Objects.requireNonNull(targetReference.get(), "navigation rail");
            writeAnimationSnapshot(
                    Objects.requireNonNull(expandedReference.get(), "expanded rail snapshot"),
                    "navigation-rail-width",
                    "expanded"
            );
            target.setExpanded(false);
        });

        runOnFxThreadWhenNavigationRailTransitionFrame(
                targetReference,
                collapsingReference,
                "navigation rail collapsing width",
                () -> {
                },
                () -> {
                    M3NavigationRail target = Objects.requireNonNull(
                            targetReference.get(),
                            "collapsing navigation rail"
                    );
                    assertNavigationRailTransitionFrame(target, "collapsing navigation rail");
                    writeAnimationSnapshot(
                            Objects.requireNonNull(collapsingReference.get(), "collapsing rail snapshot"),
                            "navigation-rail-width",
                            "collapsing"
                    );
                }
        );

        runOnFxThreadWhenNodeSnapshotStable(targetReference::get, settledReference, () -> {
            @Nullable M3NavigationRail target = targetReference.get();
            return target != null
                    && !target.isExpanded()
                    && Math.abs(target.getWidth() - target.getCollapsedContainerWidth()) <= CONTROL_EDGE_TOLERANCE
                    && firstNavigationRailItemLayout(target) == M3NavigationItemLayout.VERTICAL;
        }, "collapsed navigation rail", () -> {
        }, () -> {
            M3NavigationRail target = Objects.requireNonNull(targetReference.get(), "navigation rail");
            writeAnimationSnapshot(
                    Objects.requireNonNull(settledReference.get(), "settled rail snapshot"),
                    "navigation-rail-width",
                    "settled"
            );
            FxTestUtils.clearMotionScheme(target);
        });

        assertSnapshotChanged(
                Objects.requireNonNull(collapsedReference.get(), "collapsed rail snapshot"),
                Objects.requireNonNull(expandingReference.get(), "expanding rail snapshot"),
                "navigation rail expanding frame"
        );
        assertSnapshotChanged(
                Objects.requireNonNull(expandingReference.get(), "expanding rail snapshot"),
                Objects.requireNonNull(expandedReference.get(), "expanded rail snapshot"),
                "navigation rail expanded frame"
        );
        assertSnapshotChanged(
                Objects.requireNonNull(expandedReference.get(), "expanded rail snapshot"),
                Objects.requireNonNull(collapsingReference.get(), "collapsing rail snapshot"),
                "navigation rail collapsing frame"
        );
        assertSnapshotChanged(
                Objects.requireNonNull(collapsingReference.get(), "collapsing rail snapshot"),
                Objects.requireNonNull(settledReference.get(), "settled rail snapshot"),
                "navigation rail settled frame"
        );
    }

    /// Returns the layout of the first destination in a navigation rail.
    private static @Nullable M3NavigationItemLayout firstNavigationRailItemLayout(M3NavigationRail rail) {
        for (Node item : rail.getItems()) {
            if (item instanceof M3NavigationItem navigationItem) {
                return navigationItem.getItemLayout();
            }
        }
        return null;
    }

    /// Verifies that one animated rail frame uses coherent destination geometry and fade-through opacity.
    private static void assertNavigationRailTransitionFrame(M3NavigationRail rail, String description) {
        assertTrue(rail.getWidth() > rail.getCollapsedContainerWidth() + CONTROL_EDGE_TOLERANCE,
                () -> description + " should be wider than the collapsed endpoint: " + rail.getWidth());
        assertTrue(rail.getWidth() < rail.getExpandedContainerWidth() - CONTROL_EDGE_TOLERANCE,
                () -> description + " should be narrower than the expanded endpoint: " + rail.getWidth());

        List<M3NavigationItem> items = rail.getItems().stream()
                .filter(M3NavigationItem.class::isInstance)
                .map(M3NavigationItem.class::cast)
                .toList();
        assertFalse(items.isEmpty(), () -> description + " should contain navigation destinations");
        assertTrue(items.stream().allMatch(item -> {
                    Node content = item.lookup(".m3-navigation-item-content");
                    return content != null && content.getOpacity() < 0.9;
                }),
                () -> description + " destinations should fade while their layout changes");

        for (M3NavigationItem item : items) {
            Region indicator = assertInstanceOf(
                    Region.class,
                    item.lookup(".m3-navigation-item-indicator"),
                    description + " indicator"
            );
            double expectedHeight = item.getItemLayout() == M3NavigationItemLayout.HORIZONTAL ? 56.0 : 32.0;
            assertEquals(expectedHeight, indicator.getHeight(), CONTROL_EDGE_TOLERANCE,
                    () -> description + " should not mix " + item.getItemLayout()
                            + " layout with another state's indicator tokens: token="
                            + item.getIndicatorHeight() + ", railPseudoClasses=" + rail.getPseudoClassStates());
        }
    }

    /// Runs setup and verifies after a navigation rail reaches a real fade-through transition frame.
    private static void runOnFxThreadWhenNavigationRailTransitionFrame(
            AtomicReference<@Nullable M3NavigationRail> railReference,
            AtomicReference<@Nullable WritableImage> frameReference,
            String description,
            Runnable setup,
            Runnable verification
    ) throws InterruptedException {
        AtomicReference<String> diagnostics = new AtomicReference<>("navigation rail transition wait has not run yet");
        FxTestUtils.runOnFxThreadWhen(() -> {
            @Nullable M3NavigationRail rail = railReference.get();
            if (rail == null || rail.getScene() == null) {
                diagnostics.set(description + " rail is not attached");
                return false;
            }

            rail.getScene().getRoot().applyCss();
            rail.getScene().getRoot().layout();
            double width = rail.getWidth();
            boolean intermediateWidth = width > rail.getCollapsedContainerWidth() + CONTROL_EDGE_TOLERANCE
                    && width < rail.getExpandedContainerWidth() - CONTROL_EDGE_TOLERANCE;
            boolean fading = rail.getItems().stream()
                    .filter(M3NavigationItem.class::isInstance)
                    .map(M3NavigationItem.class::cast)
                    .map(item -> item.lookup(".m3-navigation-item-content"))
                    .allMatch(content -> content != null && content.getOpacity() < 0.9);
            if (!intermediateWidth || !fading) {
                diagnostics.set(description + " width=" + width + ", fading=" + fading);
                return false;
            }

            frameReference.set(snapshotNode(rail));
            return true;
        }, () -> "Timed out waiting for " + diagnostics.get(), setup, verification);
    }

    /// Verifies expand and collapse motion on the demo sidebar's visible drawer group.
    private static void verifySidebarDrawerGroupExpansionAnimation(
            AtomicReference<@Nullable Scene> sceneReference
    ) throws InterruptedException {
        AtomicReference<@Nullable M3NavigationDrawerGroup> targetReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> collapsedReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> expandingReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> expandedReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> collapsingReference = new AtomicReference<>();
        AtomicReference<@Nullable WritableImage> settledReference = new AtomicReference<>();

        runOnFxThreadWhenNodeAreaChanged(targetReference, collapsedReference, sceneReference, expandingReference, () -> {
            Scene scene = Objects.requireNonNull(sceneReference.get(), "scene");
            scene.getRoot().applyCss();
            scene.getRoot().layout();

            M3NavigationDrawerGroup target = Objects.requireNonNull(firstVisibleDrawerGroupWithTitle(
                    scene.getRoot(),
                    "Buttons"
            ), "sidebar drawer group");
            M3MotionSettings.setReducedMotionRequested(target, true);
            target.setExpanded(false);
            M3MotionSettings.setReducedMotionRequested(target, false);
            FxTestUtils.setMotionScheme(target, visualNavigationMotionScheme());
            scene.getRoot().applyCss();
            scene.getRoot().layout();
            targetReference.set(target);
            collapsedReference.set(snapshot(scene));
            writeAnimationSnapshot(
                    Objects.requireNonNull(collapsedReference.get(), "collapsed drawer group snapshot"),
                    "sidebar-drawer-group",
                    "collapsed"
            );
            target.setExpanded(true);
        }, () -> {
            writeAnimationSnapshot(
                    Objects.requireNonNull(expandingReference.get(), "expanding drawer group snapshot"),
                    "sidebar-drawer-group",
                    "expanding"
            );
        });

        runOnFxThreadWhenNodeAreaStable(targetReference, sceneReference, expandedReference, () -> {
            @Nullable M3NavigationDrawerGroup target = targetReference.get();
            return target != null && target.isExpanded();
        }, () -> {
        }, () -> {
            M3NavigationDrawerGroup target = Objects.requireNonNull(targetReference.get(), "sidebar drawer group");
            writeAnimationSnapshot(
                    Objects.requireNonNull(expandedReference.get(), "expanded drawer group snapshot"),
                    "sidebar-drawer-group",
                    "expanded"
            );
            assertTrue(target.isExpanded());
            target.setExpanded(false);
        });

        runOnFxThreadWhenNodeAreaChanged(targetReference, expandedReference, sceneReference, collapsingReference, () -> {
        }, () -> {
            writeAnimationSnapshot(
                    Objects.requireNonNull(collapsingReference.get(), "collapsing drawer group snapshot"),
                    "sidebar-drawer-group",
                    "collapsing"
            );
        });

        runOnFxThreadWhenNodeAreaStable(targetReference, sceneReference, settledReference, () -> {
            @Nullable M3NavigationDrawerGroup target = targetReference.get();
            return target != null && !target.isExpanded();
        }, () -> {
        }, () -> {
            M3NavigationDrawerGroup target = Objects.requireNonNull(targetReference.get(), "sidebar drawer group");
            writeAnimationSnapshot(
                    Objects.requireNonNull(settledReference.get(), "settled drawer group snapshot"),
                    "sidebar-drawer-group",
                    "settled"
            );
            assertFalse(target.isExpanded());
            FxTestUtils.clearMotionScheme(target);
        });

        assertSnapshotChanged(
                Objects.requireNonNull(collapsedReference.get(), "collapsed drawer group snapshot"),
                Objects.requireNonNull(expandingReference.get(), "expanding drawer group snapshot"),
                "sidebar drawer group expand intermediate frame"
        );
        assertSnapshotChanged(
                Objects.requireNonNull(expandingReference.get(), "expanding drawer group snapshot"),
                Objects.requireNonNull(expandedReference.get(), "expanded drawer group snapshot"),
                "sidebar drawer group expand settling frame"
        );
        assertSnapshotChanged(
                Objects.requireNonNull(expandedReference.get(), "expanded drawer group snapshot"),
                Objects.requireNonNull(collapsingReference.get(), "collapsing drawer group snapshot"),
                "sidebar drawer group collapse intermediate frame"
        );
        assertSnapshotChanged(
                Objects.requireNonNull(collapsingReference.get(), "collapsing drawer group snapshot"),
                Objects.requireNonNull(settledReference.get(), "settled drawer group snapshot"),
                "sidebar drawer group collapse settling frame"
        );
    }

    /// Returns a navigation-specific motion scheme that makes selection and disclosure frames observable.
    private static M3MotionScheme visualNavigationMotionScheme() {
        M3MotionScheme standard = M3MotionScheme.standard();
        M3MotionSpec observableSpec = M3MotionSpec.of(OBSERVABLE_MOTION_DURATION, M3MotionEasing.LINEAR);
        return M3MotionScheme.builder(standard)
                .defaultEffects(observableSpec)
                .fastSpatial(observableSpec)
                .defaultSpatial(observableSpec)
                .build();
    }

