    /// Returns the scroll pane that owns the current demo page content.
    private static ScrollPane demoPageScrollPane(Scene scene) {
        return assertInstanceOf(
                ScrollPane.class,
                demoPageHost(scene).getContent(),
                "current demo page should own a scroll pane"
        );
    }

    /// Returns the retained host that owns the current and outgoing demo page viewports.
    private static M3AnimatedContent demoPageHost(Scene scene) {
        return visibleNodesOfType(scene.getRoot(), M3AnimatedContent.class).stream()
                .filter(host -> host.getStyleClass().contains("demo-page-host"))
                .findFirst()
                .orElseThrow(() -> new AssertionError("demo page host not found"));
    }

    /// Returns whether the shared demo page host has released its outgoing page.
    private static boolean demoPageTransitionSettled(Scene scene) {
        return !demoPageHost(scene).isTransitioning();
    }

    /// Resets the current demo page scroll pane before a visual page assertion.
    private static void resetDemoPageScroll(Scene scene) {
        ScrollPane scrollPane = demoPageScrollPane(scene);
        scrollPane.setVvalue(0.0);
        scrollPane.setHvalue(0.0);
    }

    /// Drives the current demo page to one normalized scroll position while its content geometry settles.
    ///
    /// @param scene          the active demo scene
    /// @param scrollPosition the requested normalized vertical position
    /// @return `true` when both axes currently match their requested values
    private static boolean driveDemoPageScrollPosition(Scene scene, double scrollPosition) {
        ScrollPane scrollPane = demoPageScrollPane(scene);
        boolean settled = Math.abs(scrollPane.getVvalue() - scrollPosition)
                <= DEMO_PAGE_SCROLL_POSITION_TOLERANCE
                && Math.abs(scrollPane.getHvalue()) <= DEMO_PAGE_SCROLL_POSITION_TOLERANCE;
        if (!settled) {
            scrollPane.setHvalue(0.0);
            scrollPane.setVvalue(scrollPosition);
        }
        return settled;
    }

    /// Verifies one demo page after the requested scroll position has settled across real JavaFX pulses.
    private static void assertDemoPageScrollPosition(Scene scene, String pageTitle, double scrollPosition) {
        ScrollPane scrollPane = demoPageScrollPane(scene);
        assertEquals(scrollPosition, scrollPane.getVvalue(), DEMO_PAGE_SCROLL_POSITION_TOLERANCE,
                () -> pageTitle + " visual capture did not reach requested scroll position");

        if (scrollPosition >= 1.0 && pageTitle.equals("Sliders")) {
            Label finalSectionLabel = visibleNodesOfType(currentDemoPage(scene, pageTitle), Label.class).stream()
                    .filter(label -> label.getStyleClass().contains("demo-group-title"))
                    .filter(label -> label.getText().equals("Vertical"))
                    .findFirst()
                    .orElseThrow(() -> new AssertionError("Sliders page is missing the Vertical section"));
            Node viewport = Objects.requireNonNull(scrollPane.lookup(".viewport"), "demo page viewport");
            Parent finalSection = Objects.requireNonNull(
                    nearestAncestorWithStyle(finalSectionLabel, "demo-showcase-group"), "final slider section");
            Bounds finalSectionBounds = finalSection.localToScene(finalSection.getLayoutBounds());
            Bounds viewportBounds = viewport.localToScene(viewport.getBoundsInLocal());
            assertTrue(finalSectionBounds.getHeight() >= 220.0,
                    () -> "Vertical slider section did not reserve its sample height: " + finalSectionBounds);
            assertTrue(viewportBounds.contains(finalSectionBounds),
                    () -> "Bottom scroll position does not fully reveal the final Sliders section: section="
                            + finalSectionBounds + ", viewport=" + viewportBounds
                            + ", content=" + scrollPane.getContent().getLayoutBounds());
        }

        String scrollName = scrollPositionName(scrollPosition);
        writePageSnapshot(
                scene,
                "demo-scrolled-" + snapshotFileName(pageTitle) + "-" + scrollName + ".png",
                pageTitle + " " + scrollName + " scrolled section"
        );
        assertDemoPageScrolledSectionVisualGeometry(scene, pageTitle);
    }

    /// Returns whether a demo page has content below the first viewport.
    private static boolean demoPageHasVerticalOverflow(ScrollPane scrollPane) {
        @Nullable Node content = scrollPane.getContent();
        if (content == null) {
            return false;
        }

        scrollPane.applyCss();
        content.applyCss();
        if (content instanceof Parent parent) {
            parent.layout();
        }

        Bounds contentBounds = content.getLayoutBounds();
        Bounds viewportBounds = scrollPane.getViewportBounds();
        return contentBounds.getHeight() > viewportBounds.getHeight() + CONTROL_EDGE_TOLERANCE;
    }

    /// Returns a stable file-name fragment for one normalized scroll position.
    private static String scrollPositionName(double scrollPosition) {
        if (scrollPosition <= 0.0) {
            return "top";
        }
        if (scrollPosition >= 1.0) {
            return "bottom";
        }
        return "middle";
    }

    /// Scrolls the main demo page scroll pane until the supplied node is inside the viewport.
    private static void scrollDemoPageNodeIntoView(Scene scene, Node node) {
        ScrollPane scrollPane = demoPageScrollPane(scene);
        scrollPaneNodeIntoView(scrollPane, node);
        scene.getRoot().applyCss();
        scene.getRoot().layout();
    }

    /// Scrolls each ancestor `ScrollPane` until the supplied node is inside every active viewport.
    private static void scrollAncestorScrollPanesNodeIntoView(Node node) {
        List<ScrollPane> scrollPanes = ancestorScrollPanes(node);
        @Nullable Scene scene = node.getScene();
        for (int index = scrollPanes.size() - 1; index >= 0; index--) {
            Node target = index == 0 ? node : scrollPanes.get(index - 1);
            scrollPaneNodeIntoView(scrollPanes.get(index), target);
            if (scene != null) {
                scene.getRoot().applyCss();
                scene.getRoot().layout();
            }
        }
    }

    /// Returns every `ScrollPane` ancestor for a node, ordered from nearest to farthest.
    private static List<ScrollPane> ancestorScrollPanes(Node node) {
        ArrayList<ScrollPane> scrollPanes = new ArrayList<>();
        @Nullable Parent parent = node.getParent();
        while (parent != null) {
            if (parent instanceof ScrollPane scrollPane) {
                scrollPanes.add(scrollPane);
            }
            parent = parent.getParent();
        }
        return scrollPanes;
    }

    /// Scrolls a concrete `ScrollPane` until the supplied descendant node is inside its viewport.
    private static void scrollPaneNodeIntoView(ScrollPane scrollPane, Node node) {
        @Nullable Node content = scrollPane.getContent();
        if (content == null) {
            return;
        }

        scrollPane.applyCss();
        content.applyCss();
        if (content instanceof Parent parent) {
            parent.layout();
        }

        Bounds contentBounds = content.getLayoutBounds();
        Bounds viewportBounds = scrollPane.getViewportBounds();
        Bounds nodeBounds = content.sceneToLocal(node.localToScene(node.getLayoutBounds()));
        scrollPane.setVvalue(scrollValueForNode(
                nodeBounds.getMinY(),
                contentBounds.getMinY(),
                contentBounds.getHeight(),
                viewportBounds.getHeight()
        ));
        scrollPane.setHvalue(scrollValueForNode(
                nodeBounds.getMinX(),
                contentBounds.getMinX(),
                contentBounds.getWidth(),
                viewportBounds.getWidth()
        ));
        scrollPane.layout();
    }

    /// Returns the scroll value that places a node near the visible leading edge of a viewport.
    private static double scrollValueForNode(
            double nodeLeadingEdge,
            double contentLeadingEdge,
            double contentExtent,
            double viewportExtent
    ) {
        double scrollableExtent = contentExtent - viewportExtent;
        if (viewportExtent <= 0.0 || scrollableExtent <= 0.0) {
            return 0.0;
        }

        double targetLeadingEdge = Math.max(contentLeadingEdge, nodeLeadingEdge - 32.0);
        double maximumLeadingEdge = contentLeadingEdge + scrollableExtent;
        double clampedLeadingEdge = Math.min(maximumLeadingEdge, targetLeadingEdge);
        return (clampedLeadingEdge - contentLeadingEdge) / scrollableExtent;
    }

    /// Asserts that the sidebar selected indicator has no outgoing visual selection residue.
    private static void assertSidebarVisualSelectionSettled(M3FXDemoApp app, Scene scene, String pageTitle) {
        assertTrue(sidebarVisualSelectionSettled(app, scene),
                () -> "Sidebar visual selection has not settled for " + pageTitle
                        + ": " + sidebarSelectionDebug(scene));
        assertSidebarSelectionGeometry(scene, pageTitle);
    }

    /// Returns whether the sidebar selected indicator has settled on the current page only.
    private static boolean sidebarVisualSelectionSettled(M3FXDemoApp app, Scene scene) {
        scene.getRoot().applyCss();
        scene.getRoot().layout();
        String expected = app.currentPageNavigationTitle();
        if (expected == null) {
            return false;
        }

        List<M3ListItem> items = demoSidebarItems(scene.getRoot());
        List<M3ListItem> selectedItems = items.stream().filter(M3ListItem::isSelected).toList();
        if (selectedItems.size() != 1 || !expected.equals(selectedItems.get(0).getHeadlineText())) {
            return false;
        }

        for (M3ListItem item : items) {
            @Nullable Node selectionContainer = item.lookup(".m3-list-item-selection-container");
            if (selectionContainer == null) {
                return false;
            }

            if (item.isSelected()) {
                if (selectionContainer.getOpacity() < 0.995
                        || Math.abs(selectionContainer.getScaleX() - 1.0) > 0.005
                        || Math.abs(selectionContainer.getScaleY() - 1.0) > 0.005) {
                    return false;
                }
            } else if (selectionContainer.getOpacity() > 0.005) {
                return false;
            }
        }
        return true;
    }

    /// Returns a compact description of sidebar selected indicator state for assertion messages.
    private static String sidebarSelectionDebug(Scene scene) {
        StringBuilder builder = new StringBuilder();
        for (M3ListItem item : demoSidebarItems(scene.getRoot())) {
            if (!builder.isEmpty()) {
                builder.append("; ");
            }
            @Nullable Node selectionContainer = item.lookup(".m3-list-item-selection-container");
            builder.append(item.getHeadlineText())
                    .append("[selected=")
                    .append(item.isSelected())
                    .append(", opacity=");
            if (selectionContainer == null) {
                builder.append("missing");
            } else {
                builder.append(selectionContainer.getOpacity())
                        .append(", scaleX=")
                        .append(selectionContainer.getScaleX())
                        .append(", scaleY=")
                        .append(selectionContainer.getScaleY());
            }
            builder.append(']');
        }
        return builder.toString();
    }

    /// Returns compact transition, selection, and viewport diagnostics for one sidebar navigation request.
    private static String sidebarSettlementDebug(
            @Nullable M3FXDemoApp app,
            @Nullable Scene scene
    ) {
        if (app == null || scene == null) {
            return "app=" + app + ", scene=" + scene;
        }

        @Nullable String expected = app.currentPageNavigationTitle();
        @Nullable M3ListItem selectedItem = expected == null
                ? null
                : selectedDemoSidebarItem(scene.getRoot(), expected);
        @Nullable Node selectionContainer = selectedItem == null
                ? null
                : selectedItem.lookup(".m3-list-item-selection-container");
        @Nullable ScrollPane scrollPane = demoSidebarViewport(scene.getRoot());
        @Nullable Node content = scrollPane == null ? null : scrollPane.getContent();
        @Nullable Bounds selectedContentBounds = selectedItem == null || content == null
                ? null
                : content.sceneToLocal(selectedItem.localToScene(selectedItem.getBoundsInLocal()));
        return "pageTransitionSettled=" + demoPageTransitionSettled(scene)
                + ", selectionSettled=" + sidebarVisualSelectionSettled(app, scene)
                + ", selectedInsideViewport=" + selectedSidebarItemInsideViewport(app, scene)
                + ", expected=" + expected
                + ", selected=" + demoSidebarItems(scene.getRoot()).stream()
                .filter(M3ListItem::isSelected)
                .map(M3ListItem::getHeadlineText)
                .toList()
                + ", selectedBounds=" + (selectedItem == null
                ? "missing"
                : selectedItem.localToScene(selectedItem.getBoundsInLocal()))
                + ", selectedContentBounds=" + selectedContentBounds
                + ", nearestViewportBounds=" + (selectedItem == null
                ? "missing"
                : nearestScrollViewportBounds(selectedItem))
                + ", selectionContainer=" + (selectionContainer == null
                ? "missing"
                : "opacity=" + selectionContainer.getOpacity()
                + ", scaleX=" + selectionContainer.getScaleX()
                + ", scaleY=" + selectionContainer.getScaleY())
                + ", selectionState={" + sidebarSelectionDebug(scene) + "}"
                + ", scroll={" + sidebarScrollDebug(scene) + "}";
    }

    /// Returns visible navigation drawer groups that belong to the demo sidebar.
    private static List<M3NavigationDrawerGroup> demoSidebarDrawerGroups(Node root) {
        return visibleNodesOfType(root, M3NavigationDrawerGroup.class)
                .stream()
                .filter(group -> nearestAncestorWithStyle(group, "demo-sidebar-drawer") != null)
                .toList();
    }

    /// Returns visible list items that belong to the demo navigation drawer sidebar.
    private static List<M3ListItem> demoSidebarItems(Node root) {
        return visibleNodesOfType(root, M3ListItem.class)
                .stream()
                .filter(M3FXDemoVisualMatrixTest::isDemoSidebarItem)
                .toList();
    }

    /// Returns the first demo sidebar item with the supplied headline text.
    private static @Nullable M3ListItem demoSidebarItemWithText(Node root, String text) {
        for (M3ListItem item : demoSidebarItems(root)) {
            if (text.equals(item.getHeadlineText())) {
                return item;
            }
        }
        return null;
    }

    /// Returns the selected demo sidebar item with the supplied headline text.
    private static @Nullable M3ListItem selectedDemoSidebarItem(Node root, String text) {
        for (M3ListItem item : demoSidebarItems(root)) {
            if (item.isSelected() && text.equals(item.getHeadlineText())) {
                return item;
            }
        }
        return null;
    }

    /// Returns whether the current selected demo sidebar item is fully inside its scroll viewport.
    private static boolean selectedSidebarItemInsideViewport(M3FXDemoApp app, Scene scene) {
        scene.getRoot().applyCss();
        scene.getRoot().layout();
        @Nullable String expected = app.currentPageNavigationTitle();
        if (expected == null) {
            return false;
        }

        @Nullable M3ListItem selectedItem = selectedDemoSidebarItem(scene.getRoot(), expected);
        return selectedItem != null && nodeInsideNearestScrollViewport(selectedItem, CONTROL_EDGE_TOLERANCE);
    }

    /// Returns the last rendered demo sidebar item.
    private static M3ListItem lastDemoSidebarItem(Node root) {
        List<M3ListItem> items = demoSidebarItems(root);
        assertFalse(items.isEmpty(), "demo sidebar items");
        return items.get(items.size() - 1);
    }

    /// Asserts that a node is fully inside its nearest scroll viewport.
    private static void assertNodeInsideNearestScrollViewport(Node node, String description) {
        assertTrue(
                nodeInsideNearestScrollViewport(node, CONTROL_EDGE_TOLERANCE),
                () -> description + " should be visible inside its scroll viewport: node="
                        + node.localToScene(node.getBoundsInLocal())
                        + ", viewport=" + nearestScrollViewportBounds(node)
        );
    }

    /// Returns whether a node is fully inside its nearest scroll viewport.
    private static boolean nodeInsideNearestScrollViewport(Node node, double tolerance) {
        @Nullable Bounds viewportBounds = nearestScrollViewportBounds(node);
        if (viewportBounds == null) {
            return false;
        }
        Bounds nodeBounds = node.localToScene(node.getBoundsInLocal());
        return containsBoundsWithTolerance(viewportBounds, nodeBounds, tolerance);
    }

    /// Returns the nearest scroll viewport bounds for a node.
    private static @Nullable Bounds nearestScrollViewportBounds(Node node) {
        @Nullable Node viewport = nearestScrollViewport(node);
        return viewport == null ? null : viewport.localToScene(viewport.getBoundsInLocal());
    }

    /// Returns the internal Material viewport that owns demo sidebar scrolling.
    private static @Nullable ScrollPane demoSidebarViewport(Node root) {
        @Nullable Node drawer = firstVisibleStyledDescendant(root, "demo-sidebar-drawer");
        if (!(drawer instanceof M3NavigationDrawer)) {
            return null;
        }

        @Nullable Node viewport = drawer.lookup(".m3-navigation-drawer-viewport");
        return viewport instanceof ScrollPane scrollPane ? scrollPane : null;
    }

    /// Returns compact scroll diagnostics for the demo sidebar.
    private static String sidebarScrollDebug(@Nullable Scene scene) {
        if (scene == null) {
            return "scene=null";
        }
        @Nullable ScrollPane scrollPane = demoSidebarViewport(scene.getRoot());
        if (scrollPane == null) {
            return "sidebar viewport missing";
        }
        @Nullable Node content = scrollPane.getContent();
        Bounds viewportBounds = scrollPane.getViewportBounds();
        Bounds contentBounds = content == null ? new BoundingBox(0.0, 0.0, 0.0, 0.0) : content.getLayoutBounds();
        @Nullable M3ListItem scrims = demoSidebarItemWithText(scene.getRoot(), "Scrims");
        return "vvalue=" + scrollPane.getVvalue()
                + ", viewport=" + viewportBounds
                + ", content=" + contentBounds
                + ", scrims=" + (scrims == null ? "missing" : scrims.localToScene(scrims.getBoundsInLocal()));
    }

    /// Returns whether a list item is one of the demo sidebar destinations or group headers.
    private static boolean isDemoSidebarItem(M3ListItem item) {
        return item.getStyleClass().contains("demo-sidebar-top-item")
                || item.getStyleClass().contains("demo-sidebar-child-item")
                || item.getStyleClass().contains("demo-sidebar-group-item");
    }

    /// Fires one synthetic vertical wheel event from a node inside the demo sidebar.
    private static void fireVerticalWheelScroll(Node target, double deltaY) {
        Bounds bounds = target.localToScene(target.getBoundsInLocal());
        double x = bounds.getCenterX();
        double y = bounds.getCenterY();
        target.fireEvent(new ScrollEvent(
                target,
                target,
                ScrollEvent.SCROLL,
                x,
                y,
                x,
                y,
                false,
                false,
                false,
                false,
                false,
                false,
                0.0,
                deltaY,
                0.0,
                deltaY,
                ScrollEvent.HorizontalTextScrollUnits.NONE,
                0.0,
                ScrollEvent.VerticalTextScrollUnits.NONE,
                0.0,
                0,
                null
        ));
    }

    /// Verifies that grouped demo pages are nested under the expected Material sidebar parent.
    private static void assertSidebarGroupingMatchesMaterialNavigation(M3FXDemoApp app, Scene scene, String pageTitle) {
        @Nullable String sidebarTitle = app.currentPageNavigationTitle();
        assertNotNull(sidebarTitle, () -> "No current sidebar title for grouping check: " + pageTitle);
        @Nullable M3ListItem selected = selectedDemoSidebarItem(scene.getRoot(), sidebarTitle);
        assertNotNull(selected, () -> "No selected sidebar item for grouping check: " + pageTitle);

        @Nullable String expectedGroup = DEMO_PAGE_SIDEBAR_GROUPS.get(pageTitle);
        boolean childItem = selected.getStyleClass().contains("demo-sidebar-child-item");
        if (expectedGroup == null) {
            assertFalse(childItem, () -> pageTitle + " should be a top-level Material sidebar destination");
            return;
        }

        assertTrue(childItem, () -> pageTitle + " should be nested under " + expectedGroup);
        M3NavigationDrawerGroup group = Objects.requireNonNull(
                nearestAncestorOfType(selected, M3NavigationDrawerGroup.class),
                () -> pageTitle + " selected child should belong to a navigation drawer group"
        );
        assertEquals(expectedGroup, group.getTitle(),
                () -> pageTitle + " should be grouped with the matching Material component family");
        assertTrue(group.isExpanded(), () -> pageTitle + " sidebar group should be expanded when selected");
    }

    /// Verifies that the demo sidebar selected row geometry matches Material navigation drawer expectations.
    private static void assertSidebarSelectionGeometry(Scene scene, String pageTitle) {
        List<M3ListItem> selectedItems = demoSidebarItems(scene.getRoot()).stream()
                .filter(M3ListItem::isSelected)
                .toList();
        assertEquals(1, selectedItems.size(),
                () -> "Sidebar should expose one selected visual row for " + pageTitle + ": " + selectedItems);
        M3ListItem selected = selectedItems.get(0);
        @Nullable WritableImage selectedImage = snapshotIfNodeFullyVisible(scene, selected);
        if (selectedImage != null) {
            assertListItemSelectedContainerGeometry(
                    selectedImage,
                    selected,
                    "sidebar selected `" + selected.getHeadlineText() + "`"
            );
        }

        if (selected.getStyleClass().contains("demo-sidebar-child-item")) {
            M3NavigationDrawerGroup group = Objects.requireNonNull(
                    nearestAncestorOfType(selected, M3NavigationDrawerGroup.class),
                    "sidebar selected child should belong to a navigation drawer group"
            );
            assertDrawerGroupChildSelectionGeometry(group, selected, "sidebar selected child");
        } else if (selected.getStyleClass().contains("demo-sidebar-top-item")
                || selected.getStyleClass().contains("demo-sidebar-group-item")) {
            Bounds selectedBounds = selected.localToScene(selected.getBoundsInLocal());
            Bounds containerBounds = listItemSelectionContainer(selected)
                    .localToScene(listItemSelectionContainer(selected).getBoundsInLocal());
            assertEquals(selectedBounds.getMinX(), containerBounds.getMinX(), CONTROL_EDGE_TOLERANCE,
                    () -> "Sidebar top-level selected container should align to the row start: row="
                            + selectedBounds + ", container=" + containerBounds);
            assertEquals(selectedBounds.getMaxX(), containerBounds.getMaxX(), CONTROL_EDGE_TOLERANCE,
                    () -> "Sidebar top-level selected container should align to the row end: row="
                            + selectedBounds + ", container=" + containerBounds);
        }
    }

    /// Captures the current scene root as a writable image.
    private static WritableImage snapshot(Scene scene) {
        int width = Math.max(1, (int) Math.ceil(scene.getWidth()));
        int height = Math.max(1, (int) Math.ceil(scene.getHeight()));
        scene.getRoot().applyCss();
        scene.getRoot().layout();

        WritableImage sceneImage = new WritableImage(width, height);
        // The first snapshot flushes dirty Prism regions left by layout or animation pulses. The second snapshot is
        // both the fallback artifact and a reference for rejecting partially repainted Robot captures.
        scene.snapshot(sceneImage);
        scene.snapshot(sceneImage);

        @Nullable Window window = scene.getWindow();
        if (window != null && window.isShowing()) {
            if (screenCaptureRobot == null) {
                screenCaptureRobot = new Robot();
            }
            WritableImage screenImage = screenCaptureRobot.getScreenCapture(
                    new WritableImage(width, height),
                    window.getX() + scene.getX(),
                    window.getY() + scene.getY(),
                    scene.getWidth(),
                    scene.getHeight(),
                    true
            );
            if (visualSnapshotReportHasContent(screenImage)
                    && screenCaptureMatchesSceneSnapshot(screenImage, sceneImage)) {
                return screenImage;
            }
        }

        return sceneImage;
    }

    /// Returns whether a physical screen capture is consistent with the synchronously rendered scene snapshot.
    private static boolean screenCaptureMatchesSceneSnapshot(WritableImage screenImage, WritableImage sceneImage) {
        int width = Math.min((int) screenImage.getWidth(), (int) sceneImage.getWidth());
        int height = Math.min((int) screenImage.getHeight(), (int) sceneImage.getHeight());
        if (width <= 0 || height <= 0) {
            return false;
        }

        int sampleStep = Math.max(4, Math.min(width, height) / 120);
        int sampleCount = 0;
        int mismatchedSamples = 0;
        for (int y = sampleStep / 2; y < height; y += sampleStep) {
            for (int x = sampleStep / 2; x < width; x += sampleStep) {
                int screenArgb = screenImage.getPixelReader().getArgb(x, y);
                int sceneArgb = sceneImage.getPixelReader().getArgb(x, y);
                int redDifference = Math.abs(((screenArgb >>> 16) & 0xff) - ((sceneArgb >>> 16) & 0xff));
                int greenDifference = Math.abs(((screenArgb >>> 8) & 0xff) - ((sceneArgb >>> 8) & 0xff));
                int blueDifference = Math.abs((screenArgb & 0xff) - (sceneArgb & 0xff));
                int alphaDifference = Math.abs(((screenArgb >>> 24) & 0xff) - ((sceneArgb >>> 24) & 0xff));
                if (redDifference + greenDifference + blueDifference + alphaDifference > 160) {
                    mismatchedSamples++;
                }
                sampleCount++;
            }
        }

        return sampleCount > 0 && mismatchedSamples == 0;
    }

    /// Captures one standalone node as a writable image.
    private static WritableImage snapshotNode(Node node) {
        Bounds bounds = node.getLayoutBounds();
        int width = Math.max(1, (int) Math.ceil(bounds.getWidth()));
        int height = Math.max(1, (int) Math.ceil(bounds.getHeight()));
        WritableImage image = new WritableImage(width, height);
        SnapshotParameters parameters = new SnapshotParameters();
        parameters.setFill(Color.TRANSPARENT);
        node.snapshot(parameters, image);
        return image;
    }

    /// Verifies that a snapshot contains enough non-background pixels to be useful as a visual artifact.
    private static void assertSnapshotHasVisibleContent(WritableImage image, String pageTitle) {
        int contrastingPixels = 0;
        Color background = image.getPixelReader().getColor(8, 8);
        for (int y = 0; y < image.getHeight(); y++) {
            for (int x = 0; x < image.getWidth(); x++) {
                Color color = image.getPixelReader().getColor(x, y);
                if (color.getOpacity() > 0.1 && colorDistance(color, background) > 0.08) {
                    contrastingPixels++;
                }
            }
        }
        int visiblePixels = contrastingPixels;
        assertTrue(visiblePixels > image.getWidth() * image.getHeight() * 0.02,
                () -> pageTitle + " snapshot has too little visible content: " + visiblePixels);
    }

