    /// Verifies the real Chips demo page exposes each Material chip responsibility without redundant state rows.
    private static void assertChipsPageVisualState(Scene scene) {
        Parent root = scene.getRoot();
        Node page = currentDemoPage(scene, "Chips");
        assertCurrentPageTitle(scene, "Chips");
        assertVisibleText(root, "Assist Chips", "Chips");
        assertVisibleText(root, "Filter Chips", "Chips");
        assertVisibleText(root, "Input Chips", "Chips");
        assertVisibleText(root, "Suggestion Chips", "Chips");

        List<M3Chip> chips = visibleNodesOfType(page, M3Chip.class);
        assertEquals(12, chips.size(), () -> "Chips page should render twelve focused examples: " + chips);
        assertChipTypeCount(chips, M3AssistChip.class, 3, "Chips");
        assertChipTypeCount(chips, M3FilterChip.class, 3, "Chips");
        assertChipTypeCount(chips, M3InputChip.class, 3, "Chips");
        assertChipTypeCount(chips, M3SuggestionChip.class, 3, "Chips");
        assertEquals(2, chips.stream().filter(chip -> chip.getChipStyle() == M3ChipStyle.ELEVATED).count(),
                "Chips elevated count");
        assertEquals(3, chips.stream().filter(M3FXDemoVisualMatrixTest::isChipSelected).count(),
                "Chips selected count");
        assertEquals(2, chips.stream().filter(Node::isDisabled).count(), "Chips disabled count");
        assertTrue(chips.stream().filter(chip -> chip.getGraphic() != null).count() >= 5,
                "Chip responsibilities should include meaningful leading icons");
        assertEquals(3, chips.stream().filter(chip -> chip.getTrailingGraphic() != null).count(),
                "Input chip trailing action count");
        chips.stream()
                .filter(M3InputChip.class::isInstance)
                .map(M3Chip::getGraphic)
                .filter(Objects::nonNull)
                .forEach(graphic -> {
                    Bounds bounds = graphic.getLayoutBounds();
                    assertEquals(18.0, bounds.getWidth(), 0.5, "Input chip leading icon width");
                    assertEquals(18.0, bounds.getHeight(), 0.5, "Input chip leading icon height");
                });
        for (M3Chip chip : chips) {
            AccessibleRole expectedRole = chip instanceof M3SelectableChip
                    ? AccessibleRole.TOGGLE_BUTTON
                    : AccessibleRole.BUTTON;
            assertEquals(expectedRole, chip.getAccessibleRole(), () -> chip.getText() + " accessible role");
            if (chip.getTrailingGraphic() instanceof M3IconButton trailingAction) {
                assertEquals(24.0, trailingAction.getContainerWidth(), 0.0001);
                assertEquals(24.0, trailingAction.getContainerHeight(), 0.0001);
                assertTrue(trailingAction.getStyleClass().contains("m3-chip-trailing-graphic"));
            }
        }
        for (M3Chip chip : chips) {
            Node leading = chip.getGraphic();
            Node trailing = chip.getTrailingGraphic();
            if (leading == null || trailing == null || !chip.isVisible()) {
                continue;
            }
            Bounds leadingBounds = leading.localToScene(leading.getBoundsInLocal());
            Bounds trailingBounds = trailing.localToScene(trailing.getBoundsInLocal());
            if (chip.getEffectiveNodeOrientation() == NodeOrientation.RIGHT_TO_LEFT) {
                assertTrue(trailingBounds.getMaxX() <= leadingBounds.getMinX(),
                        () -> chip.getText() + " RTL trailing slot should remain at logical end");
            } else {
                assertTrue(trailingBounds.getMinX() >= leadingBounds.getMaxX(),
                        () -> chip.getText() + " trailing slot should remain at logical end");
            }
        }

        List<M3ChipGroup> groups = visibleNodesOfType(page, M3ChipGroup.class);
        assertEquals(1, groups.size(), () -> "Chips page should use one filter selection group: " + groups);
        assertEquals(M3SelectionMode.MULTIPLE, groups.get(0).getSelectionMode());
        assertEquals(2, groups.get(0).getSelectedChips().size(), "selected filter chip count");
        assertChipGroupDemoGeometry(groups.get(0));

        int geometryChecks = 0;
        for (M3Chip chip : chips) {
            @Nullable WritableImage chipImage = snapshotIfNodeFullyVisible(scene, chip);
            if (chipImage != null) {
                assertChipDemoGeometry(chipImage, chip);
                geometryChecks++;
            }
        }
        int finalGeometryChecks = geometryChecks;
        assertTrue(finalGeometryChecks >= 4,
                () -> "Chips page should verify visible geometry across all four responsibilities");
        assertDemoVectorIcons(page, "Chips", 5);
    }

