    /// Verifies the real Navigation Drawer demo page drawer and grouped destination states.
    private static void assertNavigationDrawerPageVisualState(Scene scene) {
        Parent root = scene.getRoot();
        Node page = currentDemoPage(scene, "Navigation Drawer");
        assertCurrentPageTitle(scene, "Navigation Drawer");
        assertVisibleText(root, "Standard", "Navigation Drawer");
        assertVisibleText(root, "Modal", "Navigation Drawer");
        assertVisibleText(root, "Grouped destinations", "Navigation Drawer");
        assertVisibleText(root, "Workspace", "Navigation Drawer");

        List<M3NavigationDrawer> drawers = visibleNodesOfType(page, M3NavigationDrawer.class);
        assertEquals(3, drawers.size(), () -> "Navigation Drawer page should render three drawers: " + drawers);
        for (M3NavigationDrawer drawer : drawers) {
            assertNotNull(drawer.getSelectedItem(), "drawer selected item");
        }
        assertEquals(2, drawers.stream()
                        .filter(drawer -> drawer.getVariant() == M3NavigationDrawerVariant.STANDARD)
                        .count(),
                "Navigation Drawer page should render standard and grouped standard drawers");
        M3NavigationDrawer modal = drawers.stream()
                .filter(drawer -> drawer.getVariant() == M3NavigationDrawerVariant.MODAL)
                .findFirst()
                .orElseThrow(() -> new AssertionError("Navigation Drawer page should render a modal drawer"));
        assertNotNull(modal.getEffect(), "modal drawer should resolve level-one elevation");
        assertTrue(drawers.stream()
                        .filter(drawer -> drawer.getVariant() == M3NavigationDrawerVariant.STANDARD)
                        .allMatch(drawer -> drawer.getEffect() == null),
                "standard drawers should remain at level-zero elevation");
        assertEquals(2, drawers.stream().filter(drawer -> drawer.getSelectedIndex() == 0).count(),
                "standard and modal drawers should select their first destination");
        assertTrue(drawers.stream().anyMatch(drawer -> drawer.getSelectedIndex() == 1),
                "Navigation Drawer page should render one grouped drawer selected after its group header");
        List<M3NavigationDrawerGroup> groups = visibleNodesOfType(page, M3NavigationDrawerGroup.class);
        assertEquals(1, groups.size(), "Navigation Drawer page should render one destination group");
        M3NavigationDrawerGroup group = groups.get(0);
        assertEquals("Workspace", group.getTitle(), "navigation drawer group title");
        assertTrue(group.isExpanded(), "navigation drawer group should expose its child destinations");
        assertEquals(2, group.getItems().size(), "navigation drawer group child count");
        Bounds groupHeaderBounds = group.getHeaderItem().localToScene(group.getHeaderItem().getBoundsInLocal());
        Bounds firstGroupChildBounds = group.getItems().get(0).localToScene(group.getItems().get(0).getBoundsInLocal());
        assertEquals(groupHeaderBounds.getMaxY(), firstGroupChildBounds.getMinY(), CONTROL_EDGE_TOLERANCE,
                "navigation drawer group destinations should use the zero-spacing baseline layout");
        M3ListItem selectedGroupChild = group.getItems().stream()
                .filter(M3ListItem::isSelected)
                .findFirst()
                .orElseThrow(() -> new AssertionError("navigation drawer group should select one child"));
        assertDrawerGroupChildSelectionGeometry(group, selectedGroupChild, "component drawer selected child");
        assertEquals(3, visibleNodesOfType(page, M3ListItem.class).stream().filter(M3ListItem::isSelected).count(),
                "Navigation Drawer page should render selected drawer rows");
        for (M3NavigationDrawer drawer : drawers) {
            assertNavigationDrawerDemoGeometry(scene, drawer);
        }
        List<M3Scrim> scrims = visibleNodesOfType(page, M3Scrim.class);
        assertEquals(1, scrims.size(), "Navigation Drawer page should render one modal scrim");
        M3Scrim scrim = scrims.get(0);
        assertTrue(scrim.isShown(), "modal navigation drawer scrim should be shown");
        Bounds scrimBounds = scrim.localToScene(scrim.getLayoutBounds());
        Bounds modalParentBounds = modal.getParent().localToScene(modal.getParent().getLayoutBounds());
        assertEquals(modalParentBounds.getWidth(), scrimBounds.getWidth(), CONTROL_EDGE_TOLERANCE,
                "modal scrim should fill its preview width");
        assertEquals(modalParentBounds.getHeight(), scrimBounds.getHeight(), CONTROL_EDGE_TOLERANCE,
                "modal scrim should fill its preview height");

        M3NavigationDrawer groupedDrawer = Objects.requireNonNull(
                nearestAncestorOfType(group, M3NavigationDrawer.class),
                "grouped navigation drawer"
        );
        M3NavigationDrawer scrollableDrawer = drawers.stream()
                .filter(drawer -> drawer.getItems().size() > 6)
                .findFirst()
                .orElseThrow(() -> new AssertionError("Navigation Drawer page should render long standard content"));
        ScrollPane drawerViewport = assertInstanceOf(
                ScrollPane.class,
                scrollableDrawer.lookup(".m3-navigation-drawer-viewport")
        );
        assertTrue(drawerViewport.getContent().getLayoutBounds().getHeight()
                        > drawerViewport.getViewportBounds().getHeight(),
                "long standard drawer content should exceed its independent viewport");
        assertEquals(ScrollPane.ScrollBarPolicy.NEVER, drawerViewport.getHbarPolicy(),
                "navigation drawer should not reduce the active-indicator width with a horizontal bar");
        assertTrue(M3ScrollPane.isSmoothScrollingEnabled(drawerViewport),
                "navigation drawer viewport should use Material wheel motion");
        scrollDemoPageNodeIntoView(scene, groupedDrawer);
        WritableImage groupedImage = requireSnapshotWithNodeFullyVisible(
                scene,
                groupedDrawer,
                "grouped navigation drawer"
        );
        assertListItemSelectedContainerPixels(
                groupedImage,
                listItemSelectionContainer(selectedGroupChild),
                "component drawer selected child"
        );
        assertDemoVectorIcons(page, "Navigation Drawer", 12);
    }

    /// Verifies one demo navigation drawer's selected row geometry.
    private static void assertNavigationDrawerDemoGeometry(Scene scene, M3NavigationDrawer drawer) {
        Bounds drawerBounds = drawer.localToScene(drawer.getBoundsInLocal());
        assertEquals(360.0, drawerBounds.getWidth(), CONTROL_EDGE_TOLERANCE,
                () -> "demo navigation drawer should use the baseline 360px width: " + drawerBounds);
        assertEquals(12.0, drawer.getPadding().getLeft(), CONTROL_EDGE_TOLERANCE,
                "navigation drawer outer item padding");
        assertEquals(0.0, drawer.getItemSpacing(), CONTROL_EDGE_TOLERANCE,
                "navigation drawer rows should be contiguous");
        assertNotNull(drawer.getBackground(), "navigation drawer background");
        assertFalse(drawer.getBackground().getFills().isEmpty(), "navigation drawer background fills");
        javafx.scene.layout.CornerRadii drawerRadii = drawer.getBackground().getFills().get(0).getRadii();
        boolean rightToLeft = drawer.getEffectiveNodeOrientation() == NodeOrientation.RIGHT_TO_LEFT;
        assertEquals(rightToLeft ? 16.0 : 0.0, drawerRadii.getTopLeftHorizontalRadius(),
                CONTROL_EDGE_TOLERANCE, "navigation drawer top-left radius");
        assertEquals(rightToLeft ? 0.0 : 16.0, drawerRadii.getTopRightHorizontalRadius(),
                CONTROL_EDGE_TOLERANCE, "navigation drawer top-right radius");
        M3ListItem selected = Objects.requireNonNull(drawer.getSelectedItem(), "navigation drawer selected item");
        assertTrue(selected.isSelected(), () -> "drawer selected item should expose selected state: " + selected);
        String selectedDescription = "navigation drawer selected `" + selected.getHeadlineText() + "`";
        Node selectedContainer = listItemSelectionContainer(selected);
        assertListItemSelectedContainerLayout(selected, selectedContainer, selectedDescription);
        @Nullable WritableImage selectedImage = snapshotIfNodeFullyVisible(scene, selected);
        if (selectedImage != null) {
            assertListItemSelectedContainerPixels(selectedImage, selectedContainer, selectedDescription);
        }

        List<M3ListItem> selectedRows = visibleNodesOfType(drawer, M3ListItem.class).stream()
                .filter(M3ListItem::isSelected)
                .toList();
        assertEquals(1, selectedRows.size(),
                () -> "navigation drawer should render exactly one selected row: " + selectedRows);

        for (M3ListItem item : visibleNodesOfType(drawer, M3ListItem.class)) {
            Bounds itemBounds = item.localToScene(item.getBoundsInLocal());
            assertEquals(item.getOneLineHeight(), itemBounds.getHeight(), CONTROL_EDGE_TOLERANCE,
                    () -> "navigation drawer item height should match its resolved one-line token: item="
                            + itemBounds + ", token=" + item.getOneLineHeight());
            assertEquals(56.0, itemBounds.getHeight(), CONTROL_EDGE_TOLERANCE,
                    "navigation drawer rows should use the baseline 56px height");
            boolean groupedChild = item.getStyleClass().contains("m3-navigation-drawer-group-child");
            if (groupedChild) {
                assertTrue(itemBounds.getWidth() < 336.0,
                        "grouped navigation drawer children should be indented from the logical start edge");
            } else {
                assertEquals(336.0, itemBounds.getWidth(), CONTROL_EDGE_TOLERANCE,
                        "navigation drawer rows should fill the 336px indicator area");
            }
            if (!item.isSelected()) {
                Node selectionContainer = listItemSelectionContainer(item);
                assertTrue(selectionContainer.getOpacity() <= 0.05,
                        () -> "unselected navigation drawer item should not leave selected-container residue: item="
                                + item.getHeadlineText() + ", opacity=" + selectionContainer.getOpacity());
            }
        }
    }

    /// Verifies a selected list item's selected-container layout and real pixels.
    private static void assertListItemSelectedContainerGeometry(
            WritableImage image,
            M3ListItem item,
            String description
    ) {
        Node selectionContainer = listItemSelectionContainer(item);
        assertListItemSelectedContainerLayout(item, selectionContainer, description);
        assertListItemSelectedContainerPixels(image, selectionContainer, description);
    }

    /// Verifies a selected list item's selected-container layout.
    private static void assertListItemSelectedContainerLayout(
            M3ListItemBase item,
            Node selectionContainer,
            String description
    ) {
        Bounds itemBounds = item.localToScene(item.getBoundsInLocal());
        Bounds containerBounds = selectionContainer.localToScene(selectionContainer.getBoundsInLocal());
        assertTrue(selectionContainer.getOpacity() >= 0.95
                        && selectionContainer.getScaleX() >= 0.99
                        && selectionContainer.getScaleY() >= 0.99,
                () -> description + " selected container should be fully visible: opacity="
                        + selectionContainer.getOpacity() + ", scaleX=" + selectionContainer.getScaleX()
                        + ", scaleY=" + selectionContainer.getScaleY());
        assertTrue(containsBoundsWithTolerance(itemBounds, containerBounds, CONTROL_EDGE_TOLERANCE),
                () -> description + " selected container escapes the row bounds: row="
                        + itemBounds + ", container=" + containerBounds);
        assertEquals(itemBounds.getWidth(), selectionContainer.getBoundsInLocal().getWidth(), CONTROL_EDGE_TOLERANCE,
                () -> description + " selected container local width should match the row width");
        assertEquals(itemBounds.getHeight(), selectionContainer.getBoundsInLocal().getHeight(), CONTROL_EDGE_TOLERANCE,
                () -> description + " selected container local height should match the row height");
        assertEquals(itemBounds.getCenterY(), containerBounds.getCenterY(), CONTROL_EDGE_TOLERANCE,
                () -> description + " selected container should be vertically centered in the row: row="
                        + itemBounds + ", container=" + containerBounds);
    }

    /// Verifies a selected list item's selected-container rendered pixels.
    private static void assertListItemSelectedContainerPixels(
            WritableImage image,
            Node selectionContainer,
            String description
    ) {
        Bounds containerBounds = selectionContainer.localToScene(selectionContainer.getBoundsInLocal());
        Rectangle2D pixels = contrastingPixelBounds(
                image,
                selectionContainer,
                sampleColorOutsideBounds(image, containerBounds),
                0.018
        );
        assertRectangleInsideBounds(containerBounds, pixels, CONTROL_EDGE_TOLERANCE,
                description + " selected-container pixels");
        assertTrue(pixels.getWidth() >= containerBounds.getWidth() * 0.75,
                () -> description + " selected-container pixels are too narrow: pixels="
                        + pixels + ", container=" + containerBounds);
        assertTrue(pixels.getHeight() >= containerBounds.getHeight() * 0.55,
                () -> description + " selected-container pixels are too short: pixels="
                        + pixels + ", container=" + containerBounds);
    }

    /// Verifies that a group child selected row keeps the expected physical indentation.
    private static void assertDrawerGroupChildSelectionGeometry(
            M3NavigationDrawerGroup group,
            M3ListItem child,
            String description
    ) {
        Bounds headerBounds = group.getHeaderItem().localToScene(group.getHeaderItem().getBoundsInLocal());
        Bounds childBounds = child.localToScene(child.getBoundsInLocal());
        Bounds childSelectionBounds = listItemSelectionContainer(child)
                .localToScene(listItemSelectionContainer(child).getBoundsInLocal());
        assertEquals(headerBounds.getHeight(), childBounds.getHeight(), CONTROL_EDGE_TOLERANCE,
                () -> description + " row height should match the parent header: header="
                        + headerBounds + ", child=" + childBounds);
        assertEquals(childBounds.getWidth(), childSelectionBounds.getWidth(), CONTROL_EDGE_TOLERANCE,
                () -> description + " selected child pill should fill the indented child row: child="
                        + childBounds + ", selection=" + childSelectionBounds);
        if (group.getEffectiveNodeOrientation() == NodeOrientation.RIGHT_TO_LEFT) {
            assertEquals(headerBounds.getMinX(), childBounds.getMinX(), CONTROL_EDGE_TOLERANCE,
                    () -> description + " RTL child row should align to the parent start edge: header="
                            + headerBounds + ", child=" + childBounds);
            assertTrue(childBounds.getMaxX() < headerBounds.getMaxX() - 6.0,
                    () -> description + " RTL child row should be indented from the parent end edge: header="
                            + headerBounds + ", child=" + childBounds);
        } else {
            assertEquals(headerBounds.getMaxX(), childBounds.getMaxX(), CONTROL_EDGE_TOLERANCE,
                    () -> description + " child row should align to the parent end edge: header="
                            + headerBounds + ", child=" + childBounds);
            assertTrue(childBounds.getMinX() > headerBounds.getMinX() + 6.0,
                    () -> description + " child row should be indented from the parent start edge: header="
                            + headerBounds + ", child=" + childBounds);
        }
    }

    /// Returns the selected-container node for one list item.
    private static Node listItemSelectionContainer(M3ListItemBase item) {
        return requireVisibleStyledDescendant(
                item,
                "m3-list-item-selection-container",
                "list item selected container for `" + item.getHeadlineText() + "`"
        );
    }

    /// Verifies collapsed and interactively expandable navigation rail layouts.
    private static void assertNavigationRailPageVisualState(Scene scene) {
        Parent root = scene.getRoot();
        Node page = currentDemoPage(scene, "Navigation Rail");
        assertCurrentPageTitle(scene, "Navigation Rail");
        assertVisibleText(root, "Collapsed with action", "Navigation Rail");
        assertVisibleText(root, "Narrow, centered destinations", "Navigation Rail");
        assertVisibleText(root, "Expanded standard", "Navigation Rail");
        assertVisibleText(root, "Expanded modal, full-width indicator", "Navigation Rail");
        assertVisibleText(root, "Immersive, hide when collapsed", "Navigation Rail");

        List<M3NavigationRail> rails = visibleNodesOfType(page, M3NavigationRail.class);
        assertEquals(5, rails.size(), () -> "Navigation Rail page should render five rails: " + rails);
        M3NavigationRail collapsed = rails.stream()
                .filter(rail -> !rail.isExpanded() && !rail.isNarrow())
                .findFirst()
                .orElseThrow();
        M3NavigationRail narrow = rails.stream()
                .filter(rail -> !rail.isExpanded() && rail.isNarrow())
                .findFirst()
                .orElseThrow();
        M3NavigationRail expanded = rails.stream()
                .filter(M3NavigationRail::isExpanded)
                .filter(rail -> rail.getVariant() == M3NavigationRailVariant.STANDARD)
                .findFirst()
                .orElseThrow();
        M3NavigationRail modal = rails.stream()
                .filter(M3NavigationRail::isExpanded)
                .filter(rail -> rail.getVariant() == M3NavigationRailVariant.MODAL)
                .filter(rail -> !rail.isHideWhenCollapsed())
                .findFirst()
                .orElseThrow();
        M3NavigationRail immersive = rails.stream()
                .filter(M3NavigationRail::isExpanded)
                .filter(M3NavigationRail::isHideWhenCollapsed)
                .findFirst()
                .orElseThrow();
        assertTrue(narrow.isItemsCentered(), "narrow preview should demonstrate centered destinations");
        assertTrue(narrow.getCollapsedContainerWidth() <= collapsed.getCollapsedContainerWidth(),
                "narrow rail must not be wider than the regular collapsed rail");
        assertFalse(expanded.isFullWidthIndicator(),
                "standard expanded rail should use the expressive content-hugging indicator");
        assertTrue(modal.isFullWidthIndicator(),
                "modal preview should demonstrate the optional full-width indicator");
        assertEquals(M3NavigationItemLayout.VERTICAL,
                ((M3NavigationItem) collapsed.getItems().get(0)).getItemLayout());
        assertEquals(M3NavigationItemLayout.HORIZONTAL,
                ((M3NavigationItem) expanded.getItems().get(0)).getItemLayout());
        assertEquals(
                expanded.getExpandedContainerWidth(),
                expanded.getWidth(),
                CONTROL_EDGE_TOLERANCE,
                "expanded rail should match its resolved width token"
        );
        assertEquals(
                collapsed.getCollapsedContainerWidth(),
                collapsed.getWidth(),
                CONTROL_EDGE_TOLERANCE,
                "collapsed rail should match its resolved width token"
        );
        assertNavigationRailDemoGeometry(collapsed, "collapsed navigation rail");
        assertNavigationRailDemoGeometry(narrow, "narrow centered navigation rail");
        assertNavigationRailDemoGeometry(expanded, "expanded standard navigation rail");
        assertNavigationRailDemoGeometry(modal, "expanded modal navigation rail");
        assertNavigationRailDemoGeometry(immersive, "immersive expanded navigation rail");
        assertNull(expanded.getEffect(), "standard expanded rail should stay at elevation level 0");
        assertInstanceOf(
                javafx.scene.effect.DropShadow.class,
                modal.getEffect(),
                "modal expanded rail should use elevation level 2"
        );
        assertInstanceOf(
                javafx.scene.effect.DropShadow.class,
                immersive.getEffect(),
                "immersive modal rail should use elevation level 2 while expanded"
        );
        assertEquals(5, visibleNodesOfType(page, M3IconButton.class).size(),
                "each rail preview should expose a menu toggle");
        assertEquals(1, visibleNodesOfType(page, M3FloatingActionButton.class).size(),
                "the collapsed rail should expose one primary action");
        for (M3NavigationRail rail : rails) {
            assertNotNull(rail.getHeader(), "each rail preview should install its menu inside the rail header");
        }
        assertDemoVectorIcons(page, "Navigation Rail", 26);
        assertNavigationBadgesStayCompact(scene, "Navigation Rail");
    }

    /// Verifies that the expandable rail preview menu toggles layout and item orientation in both directions.
    private static void assertNavigationRailToggleInteraction(Scene scene) {
        FxTestUtils.runOnFxThread(() -> {
            Node page = currentDemoPage(scene, "Navigation Rail");
            M3NavigationRail collapsed = visibleNodesOfType(page, M3NavigationRail.class).stream()
                    .filter(candidate -> !candidate.isExpanded() && !candidate.isNarrow())
                    .findFirst()
                    .orElseThrow();
            M3NavigationRail narrow = visibleNodesOfType(page, M3NavigationRail.class).stream()
                    .filter(candidate -> !candidate.isExpanded() && candidate.isNarrow())
                    .findFirst()
                    .orElseThrow();
            assertNavigationRailPreviewFootprintStability(scene, collapsed, narrow);

            M3NavigationRail rail = visibleNodesOfType(page, M3NavigationRail.class).stream()
                    .filter(M3NavigationRail::isExpanded)
                    .filter(candidate -> candidate.getVariant() == M3NavigationRailVariant.STANDARD)
                    .findFirst()
                    .orElseThrow();
            Parent preview = Objects.requireNonNull(rail.getParent(), "rail preview");
            M3IconButton toggle = visibleNodesOfType(preview, M3IconButton.class).stream()
                    .findFirst()
                    .orElseThrow();

            toggle.fire();
            assertFalse(rail.isExpanded(), "rail menu should collapse the expandable preview");
            assertEquals(
                    M3NavigationItemLayout.HORIZONTAL,
                    ((M3NavigationItem) rail.getItems().get(0)).getItemLayout(),
                    "horizontal item geometry should remain stable until the collapse animation settles"
            );

            toggle.fire();
            assertTrue(rail.isExpanded(), "rail menu should restore the expanded preview");
            assertEquals(
                    M3NavigationItemLayout.HORIZONTAL,
                    ((M3NavigationItem) rail.getItems().get(0)).getItemLayout()
            );

            M3NavigationRail immersive = visibleNodesOfType(page, M3NavigationRail.class).stream()
                    .filter(M3NavigationRail::isHideWhenCollapsed)
                    .findFirst()
                    .orElseThrow();
            M3IconButton hideButton = visibleNodesOfType(immersive, M3IconButton.class).stream()
                    .findFirst()
                    .orElseThrow();
            hideButton.fire();
            assertFalse(immersive.isExpanded(), "immersive rail menu should hide the rail");
            M3IconButton revealButton = immersive.getParent().getChildrenUnmodifiable().stream()
                    .filter(M3IconButton.class::isInstance)
                    .map(M3IconButton.class::cast)
                    .findFirst()
                    .orElseThrow();
            assertTrue(revealButton.isVisible(), "immersive preview should retain an external reveal action");
            revealButton.fire();
            assertTrue(immersive.isExpanded(), "external menu should restore the immersive rail");
            assertFalse(revealButton.isVisible(), "external reveal action should leave the expanded presentation");
        });
    }

    /// Verifies that expanding a collapsed rail does not resize its gallery cell or move its sibling preview.
    private static void assertNavigationRailPreviewFootprintStability(
            Scene scene,
            M3NavigationRail collapsed,
            M3NavigationRail sibling
    ) {
        Parent preview = Objects.requireNonNull(
                Objects.requireNonNull(collapsed.getParent(), "collapsed rail presentation").getParent(),
                "collapsed rail preview"
        );
        Parent siblingPreview = Objects.requireNonNull(
                Objects.requireNonNull(sibling.getParent(), "collapsed rail sibling presentation").getParent(),
                "collapsed rail sibling preview"
        );
        assertSame(preview.getParent(), siblingPreview.getParent(),
                "collapsed rail previews should share one adaptive gallery flow");

        applySceneCssAndLayout(scene);
        Bounds previewBefore = preview.getBoundsInParent();
        Bounds siblingBefore = siblingPreview.getBoundsInParent();
        double expectedFootprint = Math.max(
                collapsed.getExpandedMinimumContainerWidth(),
                Math.min(
                        Math.max(
                                collapsed.getExpandedMinimumContainerWidth(),
                                collapsed.getExpandedMaximumContainerWidth()
                        ),
                        collapsed.getExpandedContainerWidth()
                )
        );
        assertEquals(expectedFootprint, previewBefore.getWidth(), CONTROL_EDGE_TOLERANCE,
                "collapsed preview should reserve its resolved expanded footprint");

        M3IconButton toggle = visibleNodesOfType(preview, M3IconButton.class).stream()
                .filter(button -> "Expand navigation rail".equals(button.getAccessibleText()))
                .findFirst()
                .orElseThrow();
        M3MotionSettings.setReducedMotionRequested(collapsed, true);
        try {
            toggle.fire();
            applySceneCssAndLayout(scene);

            Bounds previewExpanded = preview.getBoundsInParent();
            Bounds siblingExpanded = siblingPreview.getBoundsInParent();
            assertTrue(collapsed.isExpanded(), "collapsed preview menu should expand its rail");
            assertEquals(previewBefore.getWidth(), previewExpanded.getWidth(), CONTROL_EDGE_TOLERANCE,
                    "rail expansion must not resize the reserved preview footprint");
            assertEquals(siblingBefore.getMinX(), siblingExpanded.getMinX(), CONTROL_EDGE_TOLERANCE,
                    "rail expansion must not move the sibling preview horizontally");
            assertEquals(siblingBefore.getMinY(), siblingExpanded.getMinY(), CONTROL_EDGE_TOLERANCE,
                    "rail expansion must not wrap the sibling preview to another row");

            toggle.fire();
            applySceneCssAndLayout(scene);
            Bounds siblingRestored = siblingPreview.getBoundsInParent();
            assertFalse(collapsed.isExpanded(), "second menu activation should restore the collapsed rail");
            assertEquals(siblingBefore.getMinX(), siblingRestored.getMinX(), CONTROL_EDGE_TOLERANCE,
                    "restoring the rail must preserve the sibling's horizontal position");
            assertEquals(siblingBefore.getMinY(), siblingRestored.getMinY(), CONTROL_EDGE_TOLERANCE,
                    "restoring the rail must preserve the sibling's row");
        } finally {
            if (collapsed.isExpanded()) {
                collapsed.setExpanded(false);
            }
            M3MotionSettings.setReducedMotionRequested(collapsed, false);
            applySceneCssAndLayout(scene);
        }
    }

