    /// Verifies the real Snackbars demo page buttons, compact overlay surface, actions, and queue state.
    private static void assertSnackbarsPageVisualState(Scene scene) {
        Parent root = scene.getRoot();
        Node page = currentDemoPage(scene, "Snackbars");
        assertCurrentPageTitle(scene, "Snackbars");
        assertVisibleText(root, "Snackbar Presentation", "Snackbars");
        assertVisibleText(root, "Show message", "Snackbars");
        assertVisibleText(root, "Show action", "Snackbars");
        assertVisibleText(root, "Show dismissible", "Snackbars");
        assertVisibleText(root, "Queue messages", "Snackbars");

        List<M3Button> buttons = visibleDemoPageButtons(page);
        assertEquals(4, buttons.size(), () -> "Snackbars page should render four trigger buttons: " + buttons);
        assertButtonVariantCount(buttons, M3ButtonVariant.FILLED, 1, "Snackbars");
        assertButtonVariantCount(buttons, M3ButtonVariant.TONAL, 1, "Snackbars");
        assertButtonVariantCount(buttons, M3ButtonVariant.OUTLINED, 1, "Snackbars");
        assertButtonVariantCount(buttons, M3ButtonVariant.ELEVATED, 1, "Snackbars");

        M3OverlayPane overlay = Objects.requireNonNull(firstVisibleOverlayPane(root), "overlay pane");
        assertFalse(overlay.isSnackbarShowing(), "snackbar layer should start idle");
        assertNull(overlay.getSnackbar(), "snackbar layer should not start with a visible snackbar");
        assertTrue(overlay.getSnackbarQueue().isEmpty(), "snackbar queue should start empty");

        @Nullable Duration previousDisplayDuration = overlay.snackbarDisplayDurationProperty().get();
        boolean previousReducedMotionRequested = M3MotionSettings.isReducedMotionRequested(overlay);
        M3MotionSettings.setReducedMotionRequested(overlay, true);
        overlay.setSnackbarDisplayDuration(Duration.INDEFINITE);
        try {
            M3Button messageButton = Objects.requireNonNull(
                    firstVisibleButtonWithText(page, "Show message"),
                    "message snackbar button"
            );
            messageButton.fire();
            applySceneCssAndLayout(scene);
            assertSnackbarOverlayShowsCompactMessage(scene, overlay, "Theme-aware snackbar");
            writePageSnapshot(scene, "overlay-snackbars-message.png", "Snackbars message state");

            M3Button actionButton = Objects.requireNonNull(
                    firstVisibleButtonWithText(page, "Show action"),
                    "action snackbar button"
            );
            actionButton.fire();
            applySceneCssAndLayout(scene);
            assertSnackbarOverlayShowsCompactMessage(scene, overlay, "Theme-aware snackbar");
            assertNull(firstVisibleSnackbarAction(overlay),
                    "a later snackbar must remain queued until the current message is dismissed");
            assertEquals(1, overlay.getSnackbarQueue().size(),
                    "showing an action snackbar while another message is visible should enqueue it");
            writePageSnapshot(scene, "overlay-snackbars-action-queued.png", "Queued snackbar action state");

            overlay.dismissSnackbar();
            applySceneCssAndLayout(scene);
            assertSnackbarOverlayShowsCompactMessage(scene, overlay, "Theme-aware snackbar");
            M3Button snackbarAction = Objects.requireNonNull(
                    firstVisibleSnackbarAction(overlay),
                    "action snackbar should expose its action button"
            );
            writePageSnapshot(scene, "overlay-snackbars-action.png", "Snackbars action state");
            snackbarAction.fire();
            applySceneCssAndLayout(scene);
            assertSnackbarOverlayShowsCompactMessage(scene, overlay, "Action pressed");
            overlay.dismissAllSnackbars();
            applySceneCssAndLayout(scene);

            M3Button dismissibleButton = Objects.requireNonNull(
                    firstVisibleButtonWithText(page, "Show dismissible"),
                    "dismissible snackbar button"
            );
            dismissibleButton.fire();
            applySceneCssAndLayout(scene);
            assertSnackbarOverlayShowsCompactMessage(scene, overlay, "Dismiss this message");
            M3IconButton closeButton = assertInstanceOf(
                    M3IconButton.class,
                    requireVisibleStyledDescendant(overlay, "m3-snackbar-close", "snackbar close button")
            );
            assertTrue(closeButton.isVisible());
            assertTrue(closeButton.isManaged());
            writePageSnapshot(scene, "overlay-snackbars-dismissible.png", "Snackbars dismissible state");
            closeButton.fire();
            applySceneCssAndLayout(scene);
            assertFalse(overlay.isSnackbarShowing(),
                    "snackbar close affordance should dismiss the current message");

            overlay.dismissAllSnackbars();
            applySceneCssAndLayout(scene);
            assertFalse(overlay.isSnackbarShowing(), "snackbar layer should hide before queue verification");
            assertNull(overlay.getSnackbar(), "snackbar layer should clear the dismissed snackbar");

            M3Button queueButton = Objects.requireNonNull(
                    firstVisibleButtonWithText(page, "Queue messages"),
                    "queued snackbar button"
            );
            queueButton.fire();
            applySceneCssAndLayout(scene);
            assertSnackbarOverlayShowsCompactMessage(scene, overlay, "First queued message");
            assertEquals(2, overlay.getSnackbarQueue().size(),
                    "queued snackbar demo should leave two pending messages");
            writePageSnapshot(scene, "overlay-snackbars-queued.png", "Snackbars queued state");
            overlay.dismissSnackbar();
            applySceneCssAndLayout(scene);
            assertSnackbarOverlayShowsCompactMessage(scene, overlay, "Second queued message");
            assertEquals(1, overlay.getSnackbarQueue().size(),
                    "dismissing the first queued snackbar should promote the second message");
            assertNotNull(firstVisibleSnackbarAction(overlay),
                    "the promoted queued snackbar should expose its action button");
        } finally {
            overlay.dismissAllSnackbars();
            overlay.snackbarDisplayDurationProperty().set(previousDisplayDuration);
            M3MotionSettings.setReducedMotionRequested(overlay, previousReducedMotionRequested);
            applySceneCssAndLayout(scene);
        }
    }

    /// Verifies that one bottom sheet sample keeps content, actions, and pixels inside a compact surface.
    private static void assertBottomSheetDemoGeometry(M3BottomSheet sheet, String description) {
        Bounds sheetBounds = sheet.localToScene(sheet.getBoundsInLocal());
        assertTrue(bottomSheetShown(sheet), () -> description + " should be fully shown: " + sheetBounds);
        assertTrue(sheetBounds.getWidth() >= 320.0 && sheetBounds.getWidth() <= 648.0,
                () -> description + " width should stay near the demo sheet width: " + sheetBounds);
        assertTrue(sheetBounds.getHeight() >= 160.0 && sheetBounds.getHeight() <= 420.0,
                () -> description + " height should stay compact: " + sheetBounds);
        assertSheetContentGeometry(sheet, sheet.getContent(), sheet.getActions(), description);
        assertNodeSnapshotHasOpaquePixels(sheet, description);
    }

    /// Verifies that one side sheet sample keeps content, actions, and pixels inside a compact surface.
    private static void assertSideSheetDemoGeometry(M3SideSheet sheet, String description) {
        Bounds sheetBounds = sheet.localToScene(sheet.getBoundsInLocal());
        assertTrue(sideSheetShown(sheet), () -> description + " should be fully shown: " + sheetBounds);
        assertTrue(sheetBounds.getWidth() >= 240.0 && sheetBounds.getWidth() <= 420.0,
                () -> description + " width should stay near the side sheet width: " + sheetBounds);
        assertTrue(sheetBounds.getHeight() >= 160.0 && sheetBounds.getHeight() <= 520.0,
                () -> description + " height should stay compact: " + sheetBounds);
        assertSheetContentGeometry(sheet, sheet.getContent(), sheet.getActions(), description);
        for (Node headerAction : sheet.getHeaderActions()) {
            assertTrue(headerAction.isVisible() && hasRenderableBounds(headerAction),
                    () -> description + " header action should be visible: " + headerAction);
            Bounds actionBounds = headerAction.localToScene(headerAction.getBoundsInLocal());
            assertTrue(containsBoundsWithTolerance(sheetBounds, actionBounds, CONTROL_EDGE_TOLERANCE),
                    () -> description + " header action leaves the sheet bounds: sheet="
                            + sheetBounds + ", action=" + actionBounds);
        }

        HBox headerActions = assertInstanceOf(
                HBox.class,
                sheet.lookup("." + "m3-side-sheet-header-actions"),
                description + " header actions"
        );
        assertEquals(8.0, headerActions.getSpacing(), CONTROL_EDGE_TOLERANCE,
                description + " header action spacing");

        HBox bottomActions = assertInstanceOf(
                HBox.class,
                sheet.lookup("." + "m3-side-sheet-actions"),
                description + " bottom actions"
        );
        if (sheet.getActions().isEmpty()) {
            assertFalse(bottomActions.isManaged(), description + " empty bottom action area should not consume layout");
        } else {
            assertTrue(bottomActions.isManaged(), description + " bottom action area should be managed");
            assertEquals(72.0, bottomActions.getMinHeight(), CONTROL_EDGE_TOLERANCE,
                    description + " bottom action area height");
            assertEquals(new Insets(16.0, 24.0, 24.0, 24.0), bottomActions.getPadding(),
                    description + " bottom action area padding");
        }
        assertNodeSnapshotHasOpaquePixels(sheet, description);
    }

    /// Verifies shared sheet content and action-node geometry.
    private static void assertSheetContentGeometry(
            Node sheet,
            @Nullable Node content,
            List<Node> actions,
            String description
    ) {
        Bounds sheetBounds = sheet.localToScene(sheet.getBoundsInLocal());
        assertNotNull(content, () -> description + " should expose a content node");
        Node resolvedContent = Objects.requireNonNull(content, "content");
        assertTrue(resolvedContent.isVisible() && hasRenderableBounds(resolvedContent),
                () -> description + " content should be visible: " + resolvedContent);
        Bounds contentBounds = resolvedContent.localToScene(resolvedContent.getBoundsInLocal());
        assertTrue(containsBoundsWithTolerance(sheetBounds, contentBounds, CONTROL_EDGE_TOLERANCE),
                () -> description + " content leaves the sheet bounds: sheet="
                        + sheetBounds + ", content=" + contentBounds);

        List<M3ListItem> rows = visibleNodesOfType(sheet, M3ListItem.class);
        assertEquals(3, rows.size(), () -> description + " should render three list-item rows: " + rows);
        for (M3ListItem row : rows) {
            Bounds rowBounds = row.localToScene(row.getBoundsInLocal());
            assertTrue(containsBoundsWithTolerance(sheetBounds, rowBounds, CONTROL_EDGE_TOLERANCE),
                    () -> description + " list row leaves the sheet bounds: sheet="
                            + sheetBounds + ", row=" + rowBounds);
            assertNotNull(firstVisibleDemoVectorIcon(row), () -> description + " list row should render an icon");
        }

        for (Node action : actions) {
            assertTrue(action.isVisible() && hasRenderableBounds(action),
                    () -> description + " action should be visible: " + action);
            Bounds actionBounds = action.localToScene(action.getBoundsInLocal());
            assertTrue(containsBoundsWithTolerance(sheetBounds, actionBounds, CONTROL_EDGE_TOLERANCE),
                    () -> description + " action leaves the sheet bounds: sheet="
                            + sheetBounds + ", action=" + actionBounds);
        }
    }

