    /// Verifies that a button group's public items render inside the group control bounds.
    private static void assertButtonGroupItemsInsideGroup(M3ButtonGroup group, String description) {
        Bounds groupBounds = group.localToScene(group.getBoundsInLocal());
        for (Node item : group.getItems()) {
            if (!item.isVisible() || !hasRenderableBounds(item)) {
                continue;
            }
            Bounds itemBounds = item.localToScene(item.getBoundsInLocal());
            assertTrue(containsBoundsWithTolerance(groupBounds, itemBounds, CONTROL_EDGE_TOLERANCE),
                    () -> description + " item leaves the group bounds: group="
                            + groupBounds + ", item=" + itemBounds);
        }
    }

    /// Verifies that a demo button group resolves its profile and size tokens without overriding child metrics.
    private static void assertButtonGroupTokenMetrics(
            M3ButtonGroup group,
            M3Theme theme,
            String description
    ) {
        M3ComponentTokens componentTokens = theme.tokens().componentTokens();
        M3ComponentTokens.ButtonGroupSizeTokens groupTokens = switch (group.getSize()) {
            case EXTRA_SMALL -> componentTokens.buttonGroup().extraSmall();
            case SMALL -> componentTokens.buttonGroup().small();
            case MEDIUM -> componentTokens.buttonGroup().medium();
            case LARGE -> componentTokens.buttonGroup().large();
            case EXTRA_LARGE -> componentTokens.buttonGroup().extraLarge();
        };
        M3ComponentTokens.ButtonSizeTokens buttonTokens = switch (group.getSize()) {
            case EXTRA_SMALL -> componentTokens.buttonSizing().extraSmall();
            case SMALL -> componentTokens.buttonSizing().small();
            case MEDIUM -> componentTokens.buttonSizing().medium();
            case LARGE -> componentTokens.buttonSizing().large();
            case EXTRA_LARGE -> componentTokens.buttonSizing().extraLarge();
        };
        double expectedSpacing = group.getVariant() == M3ButtonGroupVariant.STANDARD
                ? groupTokens.standardSpacing()
                : groupTokens.connectedSpacing();
        assertEquals(expectedSpacing, group.getSpacing(), 0.0001, description + " spacing");
        assertEquals(
                groupTokens.standardPressedWidthMultiplier(),
                group.getStandardPressedWidthMultiplier(),
                0.0001,
                description + " standard pressed width multiplier"
        );

        for (Node item : group.getItems()) {
            ButtonBase button = assertInstanceOf(ButtonBase.class, item, description + " item");
            if (button instanceof M3Button actionButton) {
                assertEquals(
                        buttonTokens.containerHeight(),
                        actionButton.getContainerHeight(),
                        0.0001,
                        description + " child height"
                );
                assertEquals(
                        buttonTokens.horizontalPadding(),
                        actionButton.getHorizontalPadding(),
                        0.0001,
                        description + " child horizontal padding"
                );
                assertEquals(
                        buttonTokens.iconSize(),
                        actionButton.getIconSize(),
                        0.0001,
                        description + " child icon size"
                );
            } else {
                M3IconToggleButton toggleButton =
                        assertInstanceOf(M3IconToggleButton.class, button, description + " toggle item");
                assertEquals(
                        groupTokens.containerHeight(),
                        toggleButton.getContainerHeight(),
                        0.0001,
                        description + " toggle height"
                );
            }
        }

        if (group.getVariant() != M3ButtonGroupVariant.CONNECTED || group.getItems().isEmpty()) {
            return;
        }

        double outerCorner = groupTokens.containerHeight() / 2.0;
        int itemCount = group.getItems().size();
        for (int index = 0; index < itemCount; index++) {
            ButtonBase button = assertInstanceOf(
                    ButtonBase.class,
                    group.getItems().get(index),
                    description + " child " + index
            );
            double innerCorner = theme.profile() == M3Profile.EXPRESSIVE_2025
                    && button instanceof M3IconToggleButton toggleButton && toggleButton.isSelected()
                    ? groupTokens.connectedSelectedInnerCorner()
                    : groupTokens.connectedInnerCorner();
            double topLeft = index == 0 ? outerCorner : innerCorner;
            double topRight = index == itemCount - 1 ? outerCorner : innerCorner;
            assertButtonCornerRadii(
                    button,
                    topLeft,
                    topRight,
                    topRight,
                    topLeft,
                    description + " child " + index
            );
        }
    }

    /// Verifies the four CSS-resolved background radii of one grouped button.
    private static void assertButtonCornerRadii(
            ButtonBase button,
            double topLeft,
            double topRight,
            double bottomRight,
            double bottomLeft,
            String description
    ) {
        assertNotNull(button.getBackground(), description + " background");
        assertFalse(button.getBackground().getFills().isEmpty(), description + " background fills");
        javafx.scene.layout.CornerRadii radii = button.getBackground().getFills().get(0).getRadii();
        assertEquals(topLeft, radii.getTopLeftHorizontalRadius(), 0.0001, description + " top-left radius");
        assertEquals(topLeft, radii.getTopLeftVerticalRadius(), 0.0001, description + " top-left vertical radius");
        assertEquals(topRight, radii.getTopRightHorizontalRadius(), 0.0001, description + " top-right radius");
        assertEquals(topRight, radii.getTopRightVerticalRadius(), 0.0001, description + " top-right vertical radius");
        assertEquals(bottomRight, radii.getBottomRightHorizontalRadius(), 0.0001, description + " bottom-right radius");
        assertEquals(bottomRight, radii.getBottomRightVerticalRadius(), 0.0001,
                description + " bottom-right vertical radius");
        assertEquals(bottomLeft, radii.getBottomLeftHorizontalRadius(), 0.0001, description + " bottom-left radius");
        assertEquals(bottomLeft, radii.getBottomLeftVerticalRadius(), 0.0001,
                description + " bottom-left vertical radius");
    }

    /// Verifies that the primary and menu halves of a split button remain inside the owner control.
    private static void assertSplitButtonPartsInsideOwner(M3SplitButton splitButton) {
        Bounds ownerBounds = splitButton.localToScene(splitButton.getBoundsInLocal());
        Bounds actionBounds = splitButtonActionButton(splitButton).localToScene(
                splitButtonActionButton(splitButton).getLayoutBounds()
        );
        Bounds menuBounds = splitButtonMenuButton(splitButton).localToScene(
                splitButtonMenuButton(splitButton).getLayoutBounds()
        );
        assertTrue(containsBoundsWithTolerance(ownerBounds, actionBounds, CONTROL_EDGE_TOLERANCE),
                () -> "split action button leaves owner bounds: owner="
                        + ownerBounds + ", action=" + actionBounds);
        assertTrue(containsBoundsWithTolerance(ownerBounds, menuBounds, CONTROL_EDGE_TOLERANCE),
                () -> "split menu button leaves owner bounds: owner="
                        + ownerBounds + ", menu=" + menuBounds);
        assertEquals(actionBounds.getCenterY(), menuBounds.getCenterY(), CONTROL_EDGE_TOLERANCE,
                () -> "split button halves should be vertically aligned: action="
                        + actionBounds + ", menu=" + menuBounds);
        double betweenSpace = actionBounds.getCenterX() < menuBounds.getCenterX()
                ? menuBounds.getMinX() - actionBounds.getMaxX()
                : actionBounds.getMinX() - menuBounds.getMaxX();
        assertEquals(splitButton.getSpacing(), betweenSpace, CONTROL_EDGE_TOLERANCE,
                () -> "split button should preserve its between-space: action="
                        + actionBounds + ", menu=" + menuBounds + ", spacing=" + splitButton.getSpacing());
    }

